for _stream in (sys.stdout, sys.stderr):
    # A redirected stream (a pipe, a StringIO under a harness) has no
    # reconfigure at all; asking for it by name keeps that case quiet.
    _reconfigure = getattr(_stream, "reconfigure", None)
    if _reconfigure is not None:
        try:
            _reconfigure(encoding="utf-8", errors="replace")
        except ValueError:
            pass

HERE = os.path.dirname(os.path.abspath(__file__))
TODAY = datetime.date.today().isoformat()

SECTION_FILES = ["title_abstract", "introduction", "methods", "results",
                 "discussion"]

# --- PAPER KIND (specs/review-paper.md 1) ---------------------------------
# What the document IS, which is not what it is ABOUT. `research_type` is the
# subject - surface_science, structural_bio - and it scopes the prose rules
# learned from the user's edits. `paper_kind` is the form. They are
# orthogonal: there are surface-science reviews and surface-science research
# papers, and their prose is not the same prose, so both join the rule scope
# in learn.py and neither stands in for the other.
#
# ABSENT READS AS `research`, and `paper_kind: ""` is not a third state.
# Every project that exists today has no such key and must keep behaving
# exactly as it does - the same absent-versus-empty rule `manages` needed,
# and for the same reason: defaulting a missing key to something
# consequential silently converts every project already on disk.
PAPER_KINDS = ("research", "review")
PAPER_KIND_DEFAULT = "research"

# What kind of review, which changes what is REPORTED and never what is
# RECORDED (spec 1.1). The search log is written on every kind; a narrative
# review that a reviewer later asks to make systematic cannot reconstruct the
# searches it did not log, and the log is free at the moment the search runs
# and impossible afterwards.
REVIEW_KINDS = ("narrative", "systematic", "scoping", "tutorial")
REVIEW_KIND_DEFAULT = "narrative"

# Which review kinds report their search as a Methods section, and which keep
# it as provenance in data/corpus/ only.
REVIEW_KINDS_REPORTING = ("systematic", "scoping")


def paper_kind(root: str) -> str:
    """`research` or `review`, from project.yml. Absent reads as research.

    Anything unrecognised also reads as research, deliberately: a typo in
    this key must not put a project into a mode nobody asked for, and the
    branch it would take is the one that releases checks.
    """
    value = str(read_project_yml(root).get("paper_kind", "")).strip().lower()
    return value if value in PAPER_KINDS else PAPER_KIND_DEFAULT


def review_kind(root: str) -> str:
    """`narrative` | `systematic` | `scoping` | `tutorial`. Only meaningful
    under paper_kind: review, and never consulted otherwise."""
    value = str(read_project_yml(root).get("review_kind", "")).strip().lower()
    return value if value in REVIEW_KINDS else REVIEW_KIND_DEFAULT


def is_review(root: str) -> bool:
    return paper_kind(root) == "review"


# --- SECTION STEMS, WHICH ARE A FUNCTION OF THE PROJECT (review-paper 7) ---
#
# SECTION_FILES is five fixed stems, four of them IMRaD. A review's body is N
# THEMATIC SECTIONS named by its author, and nobody but the author knows how
# many there are or what they are called - so for a review the stem list is
# derived from the project rather than enumerated here.
#
# The outline already names them. plan/outline.md's `# Structure` region
# carries `##` headings and prose.py validates the drafted sections against
# them; for paper_kind: review those headings ARE the section list, in
# document order, and the stems derive from them by slug.
#
# The NUMBER PREFIX carries document order and is the only thing that does -
# the decision plan/figures/FigNN/ already made, for the same reason: order
# in a filename beats order in a manifest nobody re-reads.

# `# Structure` / `## Heading`, and the region names prose.py already knows.
# Duplicated on purpose and pinned by tests/prose.py, like every other
# contract in this file that two engines have to agree on.
STRUCTURE_REGIONS = {"structure", "outline", "paragraph plan", "the paper"}
_H1_RE = re.compile(r"^#\s+(.+?)\s*$")
_H2_RE = re.compile(r"^##\s+(.+?)\s*$")

# Forms rather than thematic sections, and unchanged on either paper kind.
FORM_SECTIONS = ["title_abstract"]


def section_slug(heading: str) -> str:
    """`Defects and Ordering` -> `defects_and_ordering`."""
    slug = re.sub(r"[^a-z0-9]+", "_", heading.strip().lower()).strip("_")
    return slug[:48] or "section"


def outline_structure_headings(root: str) -> list[str]:
    """The `##` headings under `# Structure`, in document order."""
    text = _read(os.path.join(root, "plan", "outline.md"))
    text = re.sub(r"<!--.*?-->", "", text, flags=re.S)
    out: list[str] = []
    inside = False
    for line in text.splitlines():
        h1 = _H1_RE.match(line)
        if h1 and not line.startswith("##"):
            clean = " ".join(re.sub(r"[^a-z ]+", " ",
                                    h1.group(1).lower()).split())
            inside = clean in STRUCTURE_REGIONS
            continue
        h2 = _H2_RE.match(line)
        if h2 and inside:
            out.append(h2.group(1).strip())
    return out


def section_files(root: str) -> list[str]:
    """The stems this project's body is written in.

    A research paper gets SECTION_FILES, unchanged and unconditionally - the
    five fixed stems every existing project on disk is built from.

    A review gets `title_abstract` plus one numbered stem per `##` heading
    under `# Structure`. Renaming a heading renames the file, and the round
    snapshot in obsolete/drafts/rN/ is what makes that safe.

    A review whose outline names NO structure gets `title_abstract` alone,
    and that is deliberately a conspicuous state rather than a quiet
    fallback to the IMRaD five: a review with a Methods section it never
    asked for is worse than a review the engine says it cannot enumerate,
    and `completeness` raises the gap as blocking so the near-empty list
    cannot be mistaken for a nearly finished paper.
    """
    if paper_kind(root) != "review":
        return list(SECTION_FILES)
    headings = outline_structure_headings(root)
    stems = list(FORM_SECTIONS)
    for i, head in enumerate(headings, 1):
        stems.append("%02d_%s" % (i, section_slug(head)))
    return stems


def section_source(root: str) -> str:
    """Where the stem list came from: `scaffold`, `outline`, or `unnamed`."""
    if paper_kind(root) != "review":
        return "scaffold"
    return "outline" if outline_structure_headings(root) else "unnamed"


def body_sections(root: str) -> list[str]:
    """Everything but the forms - what `draft-sections` writes."""
    return [s for s in section_files(root) if s not in FORM_SECTIONS]


# Which sections attribution-check reads, and it is a property of what a
# SECTION IS rather than of what kind of paper this is (citation-integrity
# 6.2). Introduction and Discussion are made of sentences about other
# people's work; Results and Methods cite this project's own data and are
# stats-check's ground, so running an attribution pass over them spends
# network calls proving something no outside source can answer. Scoping it
# this way is what makes it survive a paper kind nobody has invented yet.
ATTRIBUTION_SECTIONS = ("introduction", "discussion")


def attribution_sections(root: str) -> list[str]:
    """The body sections whose sentences are about somebody else's work.

    Every body section on a review - a review declares its own structure and
    all of it is other people's work. Introduction and Discussion on any
    other kind, matched on the stem so a review-style `03_discussion` is
    caught too.
    """
    stems = body_sections(root)
    if paper_kind(root) == "review":
        return stems
    keep = []
    for stem in stems:
        name = re.sub(r"^\d{2}_", "", stem)
        if name in ATTRIBUTION_SECTIONS:
            keep.append(stem)
    return keep
# --- end SECTION STEMS -----------------------------------------------------
# --- end PAPER KIND -------------------------------------------------------

# The order draft-sections WRITES in, which is not the order the document is
# built in. `title_abstract` is first in SECTION_FILES because it is first in
# the manuscript, and an agent working that list in order wrote the abstract
# before the results it is supposed to summarize existed - the worst possible
# time to write it, and the order the engine handed over (item 19).
#
# The abstract is written last, from the finished section files, and it is
# never left empty: whatever is on the page goes in, and what is genuinely not
# there yet becomes one **[FLAG: data]** at the end of it.
DRAFT_ORDER = [s for s in SECTION_FILES if s != "title_abstract"] + \
              ["title_abstract"]

# The presets of spec 2.3. Modules are opt-in per run and the list is printed
# before anything executes, because running the whole pipeline every round is
# a listed failure mode.
# learn-from-edits is 0b and revise-prose is 1c (prose spec 2). The order
# below is the order they run in, and both positions are load-bearing:
#
#   learn-from-edits runs BEFORE draft-sections, so a section drafted this
#   round is drafted WITH the lesson in its brief rather than patched
#   afterwards. Applying without learning is what this toolkit did before -
#   the fix is paid for once and the next project starts from the same brief
#   that produced the prose the user just spent an afternoon fixing.
#
#   revise-prose runs after the drafting modules and before every checker, so
#   everything downstream sees revised prose and nothing needs to know it
#   exists. A pass that rewrote prose after `assemble` would invalidate every
#   report generated from the text and orphan the built .docx.
#
#   comprehension-check is 1d and sits AFTER revise-prose, which is the one
#   ordering decision in this list with a tempting alternative. Before 1c
#   would let the module that is allowed to rewrite act on the findings in
#   the same pass - but then the reader judges prose that is about to
#   change, and a report about text nobody will ship is a report about a
#   document that does not exist. After 1c judges what ships. The cost is
#   that nothing acts on it inside the round, and that cost is paid the way
#   this toolkit pays every cost of this shape: the fix is OFFERED, not run.
#
#   quality-check is 1e and sits after comprehension-check, at 3.62. The
#   stretch between 3.5 and 3.7 now runs: 3.5 read the paper, 3.6 act on that
#   reading, 3.62 audit the voice and the ten rules, 3.64 act on that audit,
#   3.7 attribution. It is NOT blind and comprehension-check is, which looks
#   inconsistent and is the point: a reader who knows the argument can follow
#   prose nobody else can, but you cannot tell significance inflation from a
#   significant finding without knowing what was found.
#
#   attribution-check runs on EVERY paper kind as of 2026-09-20
#   (citation-integrity 6.2, decided by the user in these words: "Lets make
#   the sentence checker work for all paper types, regardless on if its a
#   review or not"). It used to be review-only, and a research paper's
#   Introduction and Discussion - which are made of cited claims - got
#   evidence-check alone, which asks whether a citation is PRESENT and is
#   precisely the check that mistakes presence for support.
#
#   It runs BESIDE stats-check and never instead of it. They answer
#   different questions: one asks whether this project's numbers are stated
#   correctly, the other whether somebody else's paper says what this
#   sentence claims it says. On a review stats-check still goes out of scope
#   with `analysis`, which is what KIND_ONLY_MODULES below is now for.
MODULES = ["outline", "literature-landscape", "learn-from-edits",
           "draft-sections", "revise-prose",
           "comprehension-check", "quality-check",
           "evidence-check",
           "stats-check", "attribution-check",
           "assemble", "citation-check", "reviewer-check",
           "final-check", "submission-package", "respond-to-reviewers",
           "toc-graphic"]

# Which modules belong to which paper kind. A module named here for the
# other kind is taken OUT OF THE PLAN AND SAID TO BE - never left in to run
# and report nothing, which is how a user learns that a line in the plan
# means nothing.
KIND_ONLY_MODULES = {
    "stats-check": ("research",
                    "out of scope with `analysis` on a review: there are no "
                    "statistics of its own to check. A meta-analytic review "
                    "gets it back by managing `analysis`"),
    "literature-landscape": ("research",
                             "subsumed on a review: the corpus IS the "
                             "landscape, and writing "
                             "plan/literature_landscape.md beside "
                             "data/corpus/ produces two overlapping files, "
                             "one of which goes stale"),
}

# The two modules the freeze governs: both GENERATE prose, and a generating
# module runs once per section (4). Every other module checks, and a checker
# runs every round - on a frozen section it reports advisory (4.3).
GENERATING_MODULES = ["draft-sections", "revise-prose"]

# Where a round divides (item 59). Everything up to and including
# revise-prose produces PROSE; everything after it produces, checks or ships
# the SUBMISSION - the requirements sourcing, the .csl, the reference.docx,
# the built .docx, the reconciliation pass, the package.
#
# The distinction exists because "only do the introduction and methods" was
# read as scoping the drafter and nothing else. `--sections` reached two of
# the seven modules a `draft` preset resolves to; the other five ran at full
# width, and a request for two sections of prose produced a re-source of 32
# journal fields, a fetched stylesheet, a built manuscript and a citation
# pass the user had not asked for and then had to review or ignore.
#
# A request for prose is not a request for a .docx. So when the user narrows
# the round to part of the paper, the submission half is HELD and offered,
# not assumed - and the plan line asks about it as its own question rather
# than listing it beside the drafting modules under a single "Go?".
PROSE_MODULES = ["ingest", "outline", "literature-landscape",
                 "learn-from-edits", "draft-sections", "revise-prose",
                 "comprehension-check", "quality-check"]
SUBMISSION_MODULES = [m for m in MODULES if m not in PROSE_MODULES]

PRESETS = {
    # literature-landscape runs BEFORE draft-sections, in every preset that
    # drafts. The introduction was grounded almost entirely in this group's
    # own prior work because that was the only literature draft-sections was
    # given, and the fix has to be a step that happens first rather than a
    # rule the drafter is asked to remember (item 21). It is cheap on a later
    # round - an existing landscape is refreshed, not rebuilt.
    # `outline` is first in every drafting preset. No preset contained one,
    # so completing an outline happened only when the skill was steered into
    # the subcommand by hand - and draft-sections' own rule ("never invent a
    # paragraph to fill a gap the outline has not filled") is right against a
    # finished outline and wrong against notes the user has just written. The
    # engine could not tell the two apart because it never read the notes
    # (item 23). An outline that is already complete is left alone.
    # citation-check is in every preset that writes prose, and is never
    # offered as a choice (item 36). It is mechanical - every in-text citekey
    # resolves, every entry is cited, no duplicates, the count is under the
    # cap - and there is no judgment in it worth a decision. Offering it as an
    # `--add` put a yes/no question in front of the user that has one right
    # answer every time. It stays droppable, but through `--skip` in the
    # config: the user saying so ONCE, not being asked every round.
    "draft": ["outline", "literature-landscape", "learn-from-edits",
              "draft-sections", "revise-prose", "comprehension-check",
              "quality-check",
              "assemble", "citation-check"],
    # reviewer-check is in here at the user's request (2026-09-03): a draft a
    # coauthor is about to read should have been held to the journal's own
    # rules first, and that is the cheap half of the module. Which half runs
    # is the `reviewer_check` dial and the question the skill asks at plan
    # time - light on a coauthor round, heavy before submission.
    "coauthor": ["outline", "literature-landscape", "learn-from-edits",
                 "draft-sections", "revise-prose", "comprehension-check",
                 "quality-check",
                 "evidence-check", "stats-check", "attribution-check",
                 "assemble", "citation-check", "reviewer-check"],
    # toc-graphic sits before assemble: the block it writes into source_text/
    # has to exist before the .docx is built, or the graphic is simply absent
    # from the file that goes to the journal.
    "submission": ["outline", "literature-landscape", "learn-from-edits",
                   "draft-sections", "revise-prose", "comprehension-check",
                   "quality-check",
                   "toc-graphic",
                   "evidence-check", "stats-check", "attribution-check",
                   "assemble",
                   "citation-check", "reviewer-check", "final-check",
                   "submission-package"],
    "revision": ["ingest", "learn-from-edits", "draft-sections",
                 "revise-prose", "comprehension-check", "quality-check",
                 "stats-check", "attribution-check", "assemble",
                 "citation-check", "respond-to-reviewers"],
    # "only do the introduction and methods" now has an exact spelling
    # (item 59). It is the `draft` preset with the submission half taken off:
    # prose is written and polished, and nothing is built, checked against a
    # journal or shipped. `+assemble` is how a round that started here ends
    # up as a document.
    # citation-check is here because item 36's rule has no exception: it is
    # mechanical, it needs no journal requirements, no stylesheet and no
    # .docx, and every preset that writes prose runs it. What a narrow SCOPE
    # takes out of the round is a separate mechanism - the hold - and it
    # offers this module back rather than dropping it.
    "sections": ["outline", "literature-landscape", "learn-from-edits",
                 "draft-sections", "revise-prose", "comprehension-check",
                 "quality-check",
                 "citation-check"],
}

# Reconciliation is the one non-skippable module (spec 9.1): it runs on the
# final round regardless of what the user selected.
MANDATORY_ON_SUBMISSION = "citation-check"

# What a project can keep in its own folders, and therefore what `manages` may
# name. A scope the user drops is managed elsewhere: it is reported as out of
# scope rather than as a gap, and it never reaches the PAPER NOT COMPLETE block.
#
# This has to be declared rather than sniffed. "No plan/outline.md" and "the
# outline lives in the group's shared drive" look identical on disk, and the
# first is a broken scaffold while the second is a supported layout - the same
# reason `idea.py` compares a README section against the pristine template
# instead of guessing whether someone has written in it yet. Guessing here
# would either bury a real scaffold failure or fill a trimmed project's every
# build with flags about folders it was never meant to have.
MANAGED_SCOPES = ("outline", "floats", "analysis", "corpus")

# `corpus` is the scope specs/review-paper.md 2 adds, and it is the review's
# `analysis`: for a research paper data/ holds what was measured and every
# number in the prose is checked against it; for a review almost nothing was
# measured, but every sentence is a claim about somebody else's work and
# those claims are exactly as checkable, against exactly the same kind of
# record. A review with no corpus scope has nowhere to put the one artifact
# that makes its claims checkable.
#
# A research project scaffolds with analysis and not corpus; a review with
# corpus and not analysis; and a META-ANALYTIC review holds BOTH, which must
# not be refused - the numbers it computes are its own and answer to
# analysis.md, the numbers it quotes answer to the corpus, and each number
# answers to the ledger it came from.

# Written by `init` into a project that has drafts/source_text/ and no
# project.yml - a manuscript-only project, where the floats and the data are
# managed elsewhere. Deliberately the same keys as the scaffold's template so
# every reader (read_project_yml here, scaffold.py, setup.R) sees the shape it
# expects; the ones that only mean something with plan/ are left blank rather
# than filled with a plausible value.
MINIMAL_PROJECT_YML = """\
# Machine-readable project state. Written by writing-engine, because this
# project has drafts/source_text/ but was never scaffolded - the revision
# counter and the journal list had nowhere to live.
#
# `field`, `seed` and the figure-geometry presets only mean something in a
# project with plan/ and data/. They are blank here rather than guessed at.
# Run `scaffold.py check` if you later want the full structure.

title: ""
short_name: "{name}"
field:                           # chemistry | biochemistry | other
paper_kind: {paper_kind}         # research | review. Absent reads as research
target_journal: "{journal}"
research_type:                   # asked once, cached, never re-asked; see below
journals: []                     # journal folders created under drafts/
revision: 1                      # the PROJECT's round counter, across journals
rounds:                          # which journal each round belonged to
  r1: {journal_folder}
created: {today}
pi: ""
seed: 1

# research_type scopes the drafting rules learned from your edits (prose spec
# 5.5). It comes from a controlled vocabulary - `learn.py types --list` - and
# is asked once and cached here, exactly like target_journal. It is left blank
# rather than guessed: everything at layer 3 of the drafting brief is scoped by
# it, and a type invented per project scopes every rule to a population of one,
# so no rule ever reaches two observations and nothing is ever learned while
# nothing errors.
#
# Change it with `manuscript.py config <project> --journal X
# --research-type <id>`. That is a real event - the layer-3 brief changes - so
# it is reported rather than done quietly.
#
# paper_kind is the other axis and is NOT the same question: research_type is
# what the paper is ABOUT, paper_kind is what it IS. A review of this same
# subject is `paper_kind: review`, and what it manages, how its sections are
# named, which layer-0 rule holds and which modules run all change with it.
# `manuscript.py config <project> --journal X --paper-kind review
# --review-kind narrative`.
"""

# The files each scope owns, named so a report can say what went unchecked
# rather than just that something did.
SCOPE_OWNS = {
    "outline": "plan/outline.md - the claims ledger every drafted paragraph "
               "renders from",
    "floats": "plan/captions.md and plan/figures/ - the figure and table set",
    "analysis": "data/analysis/ - the statistics every number in the text is "
                "checked against",
    "corpus": "data/corpus/ - the searched, screened and verified literature "
              "every characterization in the text is checked against",
}

# What each paper kind scaffolds with. `corpus` and `analysis` are the two
# that differ, and a meta-analytic review adds `analysis` back by hand -
# `config --manages outline,floats,analysis,corpus` - which is supported and
# is not special-cased anywhere.
SCOPE_DEFAULTS = {
    "research": ("outline", "floats", "analysis"),
    "review": ("outline", "floats", "corpus"),
}

DEFAULT_CONFIG = """\
# How this pipeline is biased. Echoed back before every run, and editable by
# hand - these are your dials, not the skill's.

# 1 none | 2 loose | 3 medium | 4 tight | 5 strict. The number and the
# name are the same value, and this is the STANDING PREFERENCE - what
# the round's question offers as its default. A round's own answer
# lives in round_state.json and does not come back here unless you
# answer with `always` (writing-engine 19.3).
outline_adherence: medium
# WHO THIS PAPER IS WRITTEN FOR, and the yardstick module 1d reads. Until
# comprehension-check existed this dial was validated, written, echoed back
# before every run and read by nothing.
#   specialist  works in this subfield. Knows the techniques and the
#               standard abbreviations. Has not read this paper
#   field       a chemist or biologist outside this subfield. Knows the
#               general area, not this method
#   broad       a scientist in another discipline, or an educated
#               non-specialist, reading past the abstract
# The value is printed in the comprehension report and every finding is
# attributed to the reader who had it, because a finding whose reader is
# unstated cannot be argued with. Changing it is a REAL EVENT - the next
# report will differ for a reason that has nothing to do with the prose -
# so it is reported, exactly as research_type is.
audience: specialist           # specialist | field | broad

# Abbreviations this project does not expand, because its field does not:
# XPS, DFT, NMR. `prose.py readability` exempts element symbols, chemical
# formulae and SI units by itself - measured, those are what actually fire -
# and this is where the field's own nouns go. Add to it once.
#   known_abbreviations: [XPS, DFT, NMR]
known_abbreviations: []
# One budget applied to five sections that are not alike was the clearest
# case in this toolkit of a prohibition being too restrictive in one place and
# too loose in another at the same time: a global `low` put 8 of 11 findings on
# Methods - a section whose job is to be dull and complete - while the abstract
# sat at nearly 4x the same budget in the same list and went unnoticed.
#
# So it is per section. The scalar spelling still works and still means one
# level for every section; write one or the other, never both.
#   number_density: low
# A named level is low | medium | high. An explicit rate is
# {inline: N, clusters: N, basis: per100}; a whole-section count is
# {..., basis: absolute}, which exists for the abstract and only for the
# abstract - a rate over 250 words is noise, and the reader meets all of an
# abstract's numbers at once.
number_density:
  title_abstract: {inline: 6, clusters: 2, basis: absolute}
  introduction:   low          # a number here is a claim and needs its sentence
  methods:        high         # unenforced - dull and complete is the job
  results:        medium       # where numbers belong, and clusters are honest
  discussion:     low
number_density_waivers: []     # paragraphs where over-budget is intentional
hedging: moderate              # minimal | moderate | heavy
reviewer_check: light          # off | light | heavy
# How much of module 1d runs (specs/comprehension-check.md 6). The module
# READS the paper - it is the only one that does - and reports what it
# understood, where it stopped, and what it did not need explained. It never
# rewrites; the fix is `revise-prose --from-comprehension`, and whether
# that pass runs is `comprehension_fix` below.
#   off       not in the plan, AND the plan says it was skipped
#   light     `prose.py readability` only, no agent call
#   standard  the full blind read
# `standard` resolves to `light` at r1 - r1's prose is going to change
# anyway and the deterministic half costs nothing - and to the full read
# from r2 on. `light` set by hand stays light on every round.
comprehension_check: standard  # off | light | standard
# What happens to 1d's findings (specs/writing-engine-prose.md 12). A
# readability finding is FIXED IN THE ROUND THAT FOUND IT, before the draft
# comes back to you. Handing back a draft with a list of things wrong with it
# and nothing done about any of them is the thing this replaces.
#   auto  the pass runs, every round, and you are TOLD what it changed
#   ask   always offered - the pass never runs without your answer
#   off   the pass never runs, AND the plan says it was skipped
# Your own frozen sections are skipped outright and a coauthor's sentence is
# never overwritten silently, whatever this is set to - those are guards, not
# dials, and they are per sentence rather than per round.
comprehension_fix: auto        # auto | ask | off
# The same, for the AI-voice findings module 1e adjudicated (3.64). Separate
# from the dial above because the two passes act on different evidence: a
# reader's stumble is self-validating, an AI-voice finding is a pattern match
# that 1e has already judged before this pass sees it.
quality_fix: auto              # auto | ask | off
# Review papers only (specs/review-paper.md 5): how much of the blind
# attribution pass runs. Every sentence of a review is a claim about
# somebody else's work, so this is the review's `stats-check`.
#   off     not run, and the plan says so
#   sample  a stated, deterministic sample of the citing sentences
#   full    every citing sentence, batched by paragraph
# `sample` at r1, `full` in the submission preset. A 200-reference review at
# `full` is the most expensive thing this toolkit does, and a check nobody
# will wait for is a check that gets skipped.
attribution_check: sample      # off | sample | full
voice: active_first_person     # active_first_person | active_third | passive
# Which English the manuscript is written in. `us` means center, color,
# analyzed, sulfur; `uk` means the British forms. The engine CORRECTS this
# rather than reporting it (specs/user-asks-2026-09-18.md 3), because the
# finding names an exact word and the fix is a lookup - it is the only
# reading check here that writes. Quotations, proper nouns, code spans and
# `references.bib` are never touched, whatever this says.
#   us  the drafting brief asks for American spelling and `prose.py
#       spelling --fix` corrects anything that slipped through
#   uk  no conversion runs at all. The British-to-American map is the only
#       one built, so this setting means "leave it alone", not "convert
#       the other way", and says so rather than pretending
dialect: us                    # us | uk
response_tone: gracious        # gracious | neutral
# What kinds of source this project's reference list is allowed to carry.
#   any                 classify and report, block nothing. A preprint or a
#                       PDB entry is reported as the kind of thing it is and
#                       the decision is yours. This is the default and is
#                       right for most papers
#   peer_reviewed_only  an entry the record says is NOT peer reviewed becomes
#                       a blocking defect and is named in the not-sendable
#                       block. An entry whose record does not SAY is reported
#                       as unknown and asked about - never counted as a
#                       failure, because a bare @misc not describing itself
#                       is not evidence that it was not peer reviewed
# Dropping an entry moves every number that entry supplied. Say so first.
reference_policy: any          # any | peer_reviewed_only
length_policy: ask             # ask | over | shorten - see below
prose_polish: standard         # off | light | standard | heavy - see below
# Whether the context is cleared between stages of a round
# (specs/context-compaction.md 4.5). Every module's output to the next is
# already a FILE, so the second half of a round needs the source text, the
# journal's rules and this journal's config - none of which is in the
# conversation. What IS only in the conversation is anything you said that
# nobody wrote down, so the capture runs first and `handoff` names what it
# cannot see.
#   auto  cleared at every boundary the round crosses, ANNOUNCED in one line
#         rather than asked. A question at every boundary is how this feature
#         gets declined into uselessness
#   ask   the same, with a yes/no each time - for a round where you want to
#         keep talking about the draft
#   off   no boundary is crossed; `handoff` still works when called by hand
# Three things override this and are not settable: a module that has not
# finished, a recorded output that has changed since, and a question standing
# to you unanswered. Each one is state that is NOT on disk.
compaction: auto               # auto | ask | off

# prose_polish is how much module 1c may rewrite. It can never change what the
# text claims: every number, every citekey and every [FLAG] block is checked
# unchanged after the pass, and a section that fails is restored from its
# snapshot. That checked box is what buys the freedom inside it.
#   off       1c does not run
#   light     openers and paragraph-lead sentences only - highest value,
#             lowest risk
#   standard  the full pass, sentence and paragraph level
#   heavy     may also split/merge paragraphs and reorder sentences within one;
#             the only level permitted to change paragraph boundaries

# length_policy is what to do when the draft runs past the journal's limit.
#   ask      stop and ask, every time the draft goes over
#   over     carry the overage for now, keeping all the information; it stays
#            on the outstanding list and has to be resolved before submission
#   shorten  cut, and consolidate what will not fit into the supplement
# The ABSTRACT is not asked about: over its limit, the round cuts it under
# `ask` and `shorten` alike. Only `over` (or a frozen abstract) carries it.

# Modules you do not want run, every round, whatever the preset. This is the
# place for "I do not need the citation checker every time" - it composes with
# the presets rather than replacing them, and +module at the prompt still wins
# for a single round. citation-check comes back on a submission run regardless.
#   manuscript.py config <project> --journal X --skip citation-check
#   manuscript.py config <project> --journal X --forget citation-check
skip_modules: []

# What this project keeps in its own folders. Anything you take off this list
# is managed elsewhere - reported as out of scope rather than as a gap, and
# never named in the PAPER NOT COMPLETE block inside the .docx.
#   outline    plan/outline.md
#   floats     plan/captions.md and plan/figures/
#   analysis   data/analysis/          - a research paper's ledger
#   corpus     data/corpus/            - a review's ledger
# Dropping one says "this lives somewhere else", not "this is missing", so a
# manuscript-only project stops being told about folders it never had. An
# empty list is legitimate: source_text/ and a journal folder, nothing more.
# A scope that does not belong to this paper kind is not a question at all
# and is never reported; a meta-analytic review names both ledgers here.
manages: [outline, floats, analysis]

# Structure is copied from a style reference, never phrasing - see spec 8.2.
style_refs: []

# How much each drafting source counts. Levels: primary, normal, low, ignore.
# Anything not listed here is `normal`. A weight is INSTRUCTION TEXT in the
# drafting brief and not a coefficient: `primary` means "this source decides
# when sources disagree", `low` means "use it only where nothing else covers
# the point", and `ignore` means "do not read this file this round".
#
# It never changes which files a module is GIVEN - those lists are the
# isolation contract - with the one exception of `ignore`, which removes the
# file and is reported in the plan line every round, because a forgotten
# `ignore` is indistinguishable from a bad drafter.
#   manuscript.py config <project> --journal X --weight captions=primary
#   manuscript.py config <project> --journal X --forget-weight captions
source_weights: {}

# Free text you give at any invocation, carried into every later round until
# you drop it. This is the place to say "keep the discussion under 900 words"
# or "do not use the word novel". Add with:
#   manuscript.py config <project> --journal X --instruct "..."
custom_instructions: []
"""

# The per-section number-density block, which only a research paper's five
# fixed sections can be keyed by. A review's sections are its author's and
# are not known when the config is written, so review mode gets the scalar
# spelling - and the level is `high`, which the existing table already
# defines as *report only, no enforcement* (review-paper 4.1). No new value
# is invented for this, and the release is a DEFAULT rather than a lock:
# `number_density: low` written here by hand on a review is honoured.
_DENSITY_RESEARCH_BLOCK = """number_density:
  title_abstract: {inline: 6, clusters: 2, basis: absolute}
  introduction:   low          # a number here is a claim and needs its sentence
  methods:        high         # unenforced - dull and complete is the job
  results:        medium       # where numbers belong, and clusters are honest
  discussion:     low
"""

_DENSITY_REVIEW_BLOCK = """# Released in review mode (specs/review-paper.md 4.1). Comparing quantities
# across studies IS a review's substance: a paragraph putting six groups'
# reported coverages side by side is the paragraph doing its job. `high` is
# report-only, and it is a default, not a lock - write `low` here and it is
# honoured. What is NOT released is where each number came from: every
# number in a review's prose must appear in the record of the source its
# sentence cites, at a tier that carries numbers. That is layer 0 and no
# dial reaches it.
number_density: high
"""


def default_config(kind: str = PAPER_KIND_DEFAULT) -> str:
    """`writing_config.yml` as this paper kind starts out.

    One template with two substitutions rather than two templates, because a
    dial added to one and forgotten in the other is the failure this file has
    already paid for twice - and a review and a research paper differ in two
    lines, not in a document.
    """
    text = DEFAULT_CONFIG
    scopes = ", ".join(SCOPE_DEFAULTS.get(kind, SCOPE_DEFAULTS["research"]))
    text = text.replace("manages: [outline, floats, analysis]",
                        f"manages: [{scopes}]")
    if kind == "review":
        assert _DENSITY_RESEARCH_BLOCK in text
        text = text.replace(_DENSITY_RESEARCH_BLOCK, _DENSITY_REVIEW_BLOCK)
    return text


# --- OUTLINE ADHERENCE (writing-engine 19.2) ------------------------------
# A VERBATIM COPY of the two tables and the normalizer in `prose.py`, for the
# reason every engine here is standalone (spec 2.3): validating a dial must
# not cost an interpreter spawn, and this is read on every path that reads a
# config. `tests/prose.py` holds the two copies against each other over every
# spelling - the same treatment CAPTION_HEADING_RE and the LAYOUT CONTRACT
# get, and for the same reason: repetition is only safe while something
# compares the copies.
#
# There is no SECOND table of what a level MEANS. `prose.py` owns that, in
# ADHERENCE_NOTES, because it is the module that does the reading; what is
# copied here is the spelling, not the semantics. Everything downstream
# compares numbers.
ADHERENCE_LEVELS = {1: "none", 2: "loose", 3: "medium", 4: "tight",
                    5: "strict"}
ADHERENCE_DEFAULT = 3


def adherence_level(value: object, default: int = ADHERENCE_DEFAULT) -> int:
    """A number, from a number or from one of the five names."""
    if isinstance(value, bool):
        return default
    if isinstance(value, int):
        return value if value in ADHERENCE_LEVELS else default
    text = str(value or "").strip().lower()
    if text.isdigit() and int(text) in ADHERENCE_LEVELS:
        return int(text)
    for n, name in ADHERENCE_LEVELS.items():
        if text == name:
            return n
    return default


def adherence_label(level: int) -> str:
    """`4 (tight)` - the one spelling every printed line uses."""
    return "%d (%s)" % (level, ADHERENCE_LEVELS.get(level, "?"))


ADHERENCE_VALUES = ([str(n) for n in sorted(ADHERENCE_LEVELS)]
                    + [ADHERENCE_LEVELS[n] for n in sorted(ADHERENCE_LEVELS)])

# How many consecutive rounds at level 1 raise a `completeness` gap (19.4).
# Never a block: a project that has drafted three rounds with no claims
# ledger is one where nobody has decided what the paper argues, and that
# belongs in the PAPER NOT COMPLETE block where a coauthor sees it.
ADHERENCE_NONE_STREAK = 3
# --- end OUTLINE ADHERENCE ------------------------------------------------

# The dials, and the only values each accepts. Validated on write, because a
# typo in a dial does not fail - it silently reverts that dial to its default
# and the run is biased in a way nobody asked for.
CONFIG_DIALS = {
    # writing-engine 19.2. Five levels, in both spellings, and
    # ADHERENCE_LEVELS above is what says which number a name is.
    "outline_adherence": ADHERENCE_VALUES,
    "audience": ["specialist", "field", "broad"],
    # The scalar spelling only. A per-section mapping under this key is read
    # by prose.load_density_config(), which owns the whole contract - there is
    # no second copy of it here.
    "number_density": ["low", "medium", "high"],
    "hedging": ["minimal", "moderate", "heavy"],
    "reviewer_check": ["off", "light", "heavy"],
    # comprehension-check 6. There is no `heavy`: there is no heavier version
    # of reading the paper, and inventing one would produce an adversarial
    # reader - which is `reviewer-check --heavy`, and already exists.
    "comprehension_check": ["off", "light", "standard"],
    # prose 12.2. `auto` RUNS the rewrite pass, at every round - a readability
    # finding is fixed in the round that found it, before the draft comes
    # back. The dial is the user's ceiling over that and the round is not a
    # factor. The ratchet worry is answered by the four register floors and by
    # final-check's before/after voice diff, not by asking.
    "comprehension_fix": ["auto", "ask", "off"],
    # The same dial for the AI-voice rewrite (3.64), and it is a REAL dial as
    # of prose 12.2 - it had been hard-coded `auto` at the one call site.
    # 3.64's brief is still built from 1e's adjudicated verdicts and never
    # from raw findings (prose 10.11); this governs only whether the pass
    # then runs, which is the same question every other fix pass answers.
    "quality_fix": ["auto", "ask", "off"],
    # review-paper 5. Read only under paper_kind: review; a research project
    # carries the key and nothing consults it.
    "attribution_check": ["off", "sample", "full"],
    "voice": ["active_first_person", "active_third", "passive"],
    # user-asks-2026-09-18 3. Two values and only two, and `uk` means "run
    # nothing" rather than "convert the other way": only the British-to-
    # American map is built, and a dial that claims a direction it does not
    # have is the kind of quiet lie this file's validation exists to catch.
    "dialect": ["us", "uk"],
    "response_tone": ["gracious", "neutral"],
    # Item 105. `check-refs` classifies every entry and reports what kind it
    # is, and by design it never removes one and never refuses: a paper may
    # legitimately cite a preprint or a PDB record, and that decision is the
    # user's. That default is right and it is unchanged - `any` is the
    # default and behaves exactly as before.
    #
    # What was missing is any way for a project that HAS decided to make the
    # decision stick. On such a project the rule lived in whoever remembered
    # it: a review carried a UniProt accession as a numbered reference
    # through a full round before a reader challenged it, and the
    # peer-reviewed-only rule for that project then lived in an assistant's
    # memory file rather than in the project.
    #
    # The three-valued `peer_reviewed` flag survives the policy and that is
    # the care this dial needs. `False` is the record SAYING it was not peer
    # reviewed and is what blocks; `None` is the entry not saying, which is
    # the common case and is reported as a question, never counted as a
    # failure.
    "reference_policy": ["any", "peer_reviewed_only"],
    # What to do when the draft runs past the journal's limit. `ask` is the
    # default because the answer is the user's and it is not obvious: an
    # overlong draft that has all the information in it is a normal, useful
    # state to be in, and cutting to fit before the science is settled throws
    # away material that has to be written twice.
    "length_policy": ["ask", "over", "shorten"],
    # How much module 1c may rewrite (prose 3.3). `standard` is the default
    # because the pass is bounded by checked invariants rather than by trust:
    # it cannot change a number, a citekey or a flag whatever this is set to.
    "prose_polish": ["off", "light", "standard", "heavy"],
    # context-compaction 4.5. Whether the context is cleared at the
    # boundaries a round crosses. `auto` is the default and it is a
    # DELIBERATE REVERSAL of this toolkit's usual "offer, never run": every
    # other dial governs something that writes to the project folder, and a
    # compaction writes nothing. Its whole content is forgetting, the
    # forgetting is bounded by the pre-clear capture, and the run ledger means
    # the worst case is re-reading a file. So the cost of a wrong `auto` is
    # tokens, and the cost of a wrong `ask` is that the feature is declined
    # forever and the 219 KB skill split was paid for nothing.
    "compaction": ["auto", "ask", "off"],
}

# `skip_modules` is a standing drop list, not a preset override. The name says
# what it does: naming it `modules` invited reading it as "the modules to run",
# and a list that replaces the preset freezes the pipeline at whatever the user
# wrote once - the round they target a different journal, or move from drafting
# to submission, the preset is the thing that should change and the standing
# preference should still compose with it.
CONFIG_LISTS = ["number_density_waivers", "style_refs", "custom_instructions",
                "skip_modules", "manages", "known_abbreviations"]

# Lists whose members come from a closed set, checked the same way a dial's
# value is and for the same reason: a typo does not fail. `manages: [flotas]`
# would silently take the float checks out of the run, and the build would look
# clean because the checks that would have complained were the ones removed.
CONFIG_LIST_VALUES = {"manages": MANAGED_SCOPES}

# A list key absent from the file entirely means "not answered", which is not
# the same as an empty list. Only `manages` cares: a project written before
# this key existed manages everything, while `manages: []` is a deliberate
# statement that it manages nothing. Defaulting a missing key to `[]` would
# silently turn every older project into a trimmed one.
#
# The default is the RESEARCH scope set, not every scope: a project written
# before `corpus` existed is a research project, and defaulting it to manage
# a data/corpus/ it was never meant to have would put a missing-corpus line
# in the PAPER NOT COMPLETE block of every paper already on disk. A review
# always carries the key explicitly - scaffold.py's review template and
# `init --paper-kind review` both write it - so the absent case never
# reaches one.
CONFIG_LIST_DEFAULTS = {"manages": list(SCOPE_DEFAULTS["research"])}

# A third kind of config key: a MAPPING. `source_weights` is one because the
# question it answers is per-source ("how much does this one count"), and a
# list cannot carry that. Parsed like a list - a block of indented entries
# under the key - and validated like a dial, because the failure is the same
# one: a typo does not fail, it silently biases the run.
CONFIG_MAPS = ["source_weights"]

# Every field of spec 4.1, pre-seeded as unknown. Guidelines are the most
# tempting thing in this pipeline to hallucinate, because they are formulaic
# and a plausible invented value reads as correct. A field is either sourced
# or it is unknown - there is no third state and no inference from similar
# journals (spec 4.3).
REQUIREMENTS_SKELETON = """\
# Machine-readable journal requirements. The formatter reads this file, so
# every value here has to have come from the journal's own page.
#
# RULES (spec 4.3):
#   - unknown is a legitimate value and the only alternative to a sourced one
#   - every non-unknown value carries its URL in sources: below
#   - anything still unknown at submission is listed at the top of
#     requirements.md under "Could not determine - verify before submission"

journal: "{journal}"
checked: {today}

text:
  word_limit_total: unknown
  word_limit_abstract: unknown
  word_limit_intro: unknown
  word_limit_discussion: unknown
  word_limit_counts: unknown      # what the total includes - body only? refs?
  font_family: unknown
  font_size_pt: unknown
  line_spacing: unknown
  line_numbers: unknown
  page_numbers: unknown           # left off only if the journal says so
  justification: unknown          # justified | left (pandoc's default)
  margins_in: unknown             # all four sides
  # margin_top_in / margin_bottom_in / margin_left_in / margin_right_in
  # override one side each, for a journal that asks for a wide binding edge
  columns: unknown
  page_size: unknown
  # Items 139/151. A list of section names from section_order, or
  # every_section, or none. `unknown` puts a page break before every
  # top-level heading (the engine default, said in requirements.md).
  page_break_before: unknown
  # Item 152. none | a length (0.5in, 1.27cm, 36pt). `unknown` indents
  # BodyText 0.5 in and nothing else (the engine default, said likewise).
  first_line_indent: unknown

structure:
  section_order: [title_abstract, introduction, methods, results, discussion]
  abstract_type: unknown          # structured | unstructured
  abstract_headings: unknown
  keyword_count: unknown
  subheadings_permitted: unknown
  required_statements: unknown    # data availability, COI, funding, contributions
  statement_sections:             # the end matter, one line each. assemble
    supporting_information: unknown   # writes a section for every one that is
    author_information: unknown       # required, and flags the ones authors.md
    author_contributions: unknown     # has nothing for. required | encouraged |
    funding: unknown                  # required_if_used | unknown
    conflict_of_interest: unknown
    data_availability: unknown
    ethics: unknown
    acknowledgment: unknown

figures:
  max_count: unknown
  width_single_in: unknown
  width_double_in: unknown
  dpi_raster: unknown
  dpi_line: unknown
  file_format: unknown
  color_mode: unknown
  placement: unknown              # embedded | separate
  caption_placement: unknown
  caption_word_cap: unknown
  citation_style: unknown         # parenthetical | running_text | either
  file_naming: unknown            # the journal's own example of an uploaded
                                  # figure file name, verbatim - "Figure 1.tif".
                                  # The digits in it are the placeholder; every
                                  # other character is literal.

tables:
  max_count: unknown
  format: unknown                 # editable | image
  caption_placement: unknown
  footnote_markers: unknown
  citation_style: unknown         # parenthetical | running_text | either

review:                           # only consulted under paper_kind: review
  types_accepted: unknown         # which kinds of review this journal takes
  word_limit: unknown             # reviews usually have their own, and it is
                                  # usually not the research limit
  abstract_type: unknown          # structured | unstructured
  prisma_required: unknown
  search_report_required: unknown # is the search reported as a Methods
                                  # section, or kept as provenance
  registration_required: unknown  # PROSPERO and its equivalents. THE ONE
                                  # REQUIREMENT WHOSE LATENESS CANNOT BE
                                  # REPAIRED - a systematic review that
                                  # should have been registered before
                                  # screening cannot be registered
                                  # afterwards, so this is reported at init
                                  # and at the first corpus build, never at
                                  # submission where the news is useless
  declaration_no_new_data: unknown

references:
  style_name: unknown
  csl: unknown                    # the CSL file name in journal_requirements/
  max_count: unknown
  numbered: unknown
  journal_abbreviations: unknown
  doi_required: unknown

supplementary:
  permitted_types: unknown
  naming: unknown
  captions_in_main_file: unknown
  file_format: unknown            # pdf | docx | either (item 155)
  large_tables: unknown           # separate | inline - separate exports
                                  # the large ones as .csv beside the file
  content_restrictions: unknown   # the journal's own words, verbatim, on
                                  # what a supplement may not hold (156)

# Item 153. Every source the capture read only part of, one line each, with
# what was not read. A non-empty list keeps the package NOT SENDABLE: a rule
# in the unread half is a rule nothing encodes and nothing checks.
capture:
  partly_read: []

submission:
  cover_letter: unknown
  suggested_reviewers: unknown
  # WHERE the reviewer list goes, which is a different question from whether
  # the journal wants one. Many want the names IN the cover letter and no
  # second file; some want a separate upload; some collect them in the portal
  # and want neither. `unknown` writes the standalone file, which is the safe
  # default: a list the journal did not want is a file nobody opens, and a
  # list folded into a letter the journal wanted separately is a list that
  # never arrives.
  suggested_reviewers_in: unknown  # cover_letter | separate | portal |
                                   #   unknown
  orcid_required: unknown
  preprint_policy: unknown
  fees: unknown
  # The journal's own competing-interest FORM - the blank one every author has
  # to sign, not the statement printed in the paper. Recorded here so the URL
  # is read once and the form is fetched once, into
  # plan/author_information/conflict_statements/blank_form/.
  coi_form: unknown                # required | not_required | unknown
  coi_form_url: ""                 # where the blank form was downloaded from

# Read by tools/toc_graphic.py. These key names are the contract: the engine
# reads THESE, and the older spellings it used to look for (`term`,
# `file_formats`, `font_min_pt`, `font_preferred_pt`, `label`,
# `must_differ_from_figures`) are still accepted for files already written but
# are not what a new file should use. Do not rename them per project - a
# requirements block whose names the engine does not read is a value silently
# lost, which is what item 10 was.
toc_graphic:
  required: unknown               # true | false | unknown
  journal_term: unknown           # the journal's own word for it, verbatim
  folder_name: unknown            # optional; derived from journal_term if not set
  width_in: unknown
  height_in: unknown
  dpi_color: unknown
  dpi_bw: unknown
  file_format: unknown            # e.g. [TIF, EPS]
  color_mode: unknown
  font_family: unknown
  font_size_pt_min: unknown
  font_size_pt_preferred: unknown
  label_text: unknown             # e.g. "For Table of Contents Only"
  placement: unknown
  may_reuse_figure: unknown       # false where the journal forbids reuse.
                                  # NOTE the sense: this is the journal's own
                                  # framing, and it is the inverse of the
                                  # engine's must_differ_from_figures.
  must_be_original: unknown
  prohibited_content: unknown

# Typography this journal decides and the house does not
# (specs/user-asks-2026-09-18-second.md 1.2 and 3.2). Both keys SUPERSEDE the
# house default without argument, and the report says which rule it applied -
# a check that silently picks a house is how a paper gets formatted for the
# wrong journal.
typography:
  # Terms this journal sets ITALIC that the house leaves roman. The house
  # fires on none of `et al., i.e., e.g., cf., vs., per se, via` by default,
  # because they are genuinely disputed. e.g. [et al., i.e.]
  italic_terms: unknown
  # Terms this journal sets ROMAN that the house italicises. ACS treats
  # `in vivo` and `in vitro` as naturalised English; write them here and the
  # italics pass leaves them alone. e.g. [in vivo, in vitro]
  roman_terms: unknown
  # Whether an abbreviation is defined in the ABSTRACT. The house rule is
  # `define` - define it in the abstract and define it again at first use in
  # the body, because each is read alone. Some journals forbid abbreviations
  # in an abstract entirely; that is `avoid`, and it inverts the finding.
  abbreviations_in_abstract: unknown   # define | avoid | unknown

# AI-use disclosure (spec 17). Three genuinely different obligations - a
# statement in the paper, a declaration in the submission, or an explicit
# statement that none is needed - and a journal can want more than one.
#
# `unknown` here is NOT exempt from rule 1 above and must not be given a
# plausible default: a wrongly-worded declaration is worse than an absent one,
# because it is a false statement about how the paper was written.
ai_disclosure:
  required: unknown          # yes | no | unknown
  in_paper: unknown          # no | statement | methods | acknowledgments
  in_paper_heading: ""       # the journal's exact heading, verbatim
  in_paper_position: ""      # e.g. before_references
  in_submission: unknown     # no | cover_letter | separate_form |
                             #   portal_checkbox
  scope: ""                  # what the journal says must be declared
  exempt: ""                 # what it says needs no declaration
  source: ""                 # the URL the above was read from
  read_on: ""                # the date it was read

sources: {{}}
"""

# The values figures.citation_style / tables.citation_style may take. Anything
# else in the file - including the `unknown` that means nobody has looked yet -
# leaves the callout form unchecked rather than guessed at.
CALLOUT_STYLES = ("parenthetical", "running_text", "either")

# requirements.yml key -> the scope prose.py length knows it by.
LENGTH_LIMIT_KEYS = {
    "text.word_limit_total": "total",
    "text.word_limit_abstract": "abstract",
    "text.word_limit_intro": "introduction",
    "text.word_limit_discussion": "discussion",
    "figures.max_count": "figures_max",
    "tables.max_count": "tables_max",
}

CONFLICT_COPY_RE = re.compile(r"-DESKTOP-[A-Z0-9]+(-\d+)?", re.IGNORECASE)
EDIT_FILENAME_RE = re.compile(
    r"^manuscript_r(\d+)_([A-Za-z]{1,4})\.docx$", re.IGNORECASE)
REVIEWER_FILENAME_RE = re.compile(
    r"^reviewer_report_r(\d+)(?:_(\w+))?\.(pdf|docx|md|txt)$", re.IGNORECASE)


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def _read(path: str) -> str:
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read()
    except OSError:
        return ""


def _write(path: str, text: str) -> None:
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)


def _sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def read_project_yml(root: str) -> dict:
    """Flat `key: value` pairs. The same hand parser scaffold.py and idea.py
    use, and for the same reason: no dependency."""
    out: dict = {}
    for line in _read(os.path.join(root, "project.yml")).splitlines():
        line = line.split("#", 1)[0].rstrip()
        m = re.match(r"^([a-z_]+):\s*(.*)$", line)
        if m:
            out[m.group(1)] = m.group(2).strip().strip('"').strip("'")
    return out


def _quote_closed(val: str) -> bool:
    """True when a value opening with a quote also closes with one.

    Only ever asked about a value that starts with `"` or `'`, so "closed" is
    a matching quote at the end and nothing subtler; requirements.yml is
    written by hand from a journal's page, not generated.
    """
    q = val[:1]
    return len(val) > 1 and val.rstrip().endswith(q)


# Where `read_flat_yml` files the ITEMS of a block list, beside the bracketed
# string it also files under the plain key. Not a dotted path and not a legal
# YAML key, so it can never collide with something a journal wrote.
def _strip_yaml_comment(line: str) -> str:
    """The line with its trailing comment cut off, HONOURING QUOTES.

    Item 122. A `#` inside quotes is a character, and a journal's
    footnote-marker sequence is exactly that: an inline list containing
    `"#"` was cut at that element and the file then refused as a list that
    is never closed - so a sourced requirement made the whole file
    unreadable. The requirements.yml this toolkit ships even carries a
    comment telling the author never to write a `#` in a value, which is a
    workaround documented in the data because the reader could not do it.

    A `#` is also only a comment when it opens the line or follows
    whitespace, which is YAML's own rule and the reason `a#b` is a value.
    """
    out: list[str] = []
    quote = ""
    escaped = False
    for i, ch in enumerate(line):
        if quote:
            out.append(ch)
            if escaped:
                escaped = False
            elif quote == '"' and ch == "\\":
                escaped = True
            elif ch == quote:
                quote = ""
            continue
        if ch in "\"'":
            quote = ch
        elif ch == "#" and (i == 0 or line[i - 1] in " 	"):
            break
        out.append(ch)
    return "".join(out)


LIST_ITEMS_PREFIX = "[]"


def read_flat_yml(path: str, problems: list[str] | None = None) -> dict:
    """Nested `key: value` out of a two-level flat file, as
    {"text.font_size_pt": "unknown"}. Enough for requirements.yml and
    writing_config.yml, which are flat by design.

    A list is accepted in either spelling and always read back bracketed.
    The inline form was the only one understood, and requirements.yml is
    written by hand from a journal's guidelines - so a section order written
    as a block list

        section_order:
          - Title
          - Abstract

    parsed as the empty string, `section_order()` fell back to the scaffold's
    five files, and nothing said so: measured on a real Langmuir folder, an
    eleven-section order captured correctly from the guidelines was silently
    replaced at build time. Same family as gate 0 - a value that reads as
    absent rather than as itself.

    An inline list may also run over several lines - an eleven-section order
    captured from a journal's guidelines does not fit on one - and the third
    door into the same bug was that only the first line was read:

        section_order: [Title, Author List, Abstract, Introduction,
                        Experimental Section, Results and Discussion]

    kept four sections and dropped two, and the build exited 0 with the
    manuscript short of its Experimental Section and Results. Continuation
    lines are now read to the closing `]`.

    An inline list that is never closed cannot be read at all, and that is
    the one case this reader cannot fix quietly. Pass a `problems` list to be
    told about it; the callers that build a document do, and refuse.

    A **quoted scalar** may wrap the same way, and did:

        prohibited_content: "photographs, drawings or caricatures of any
          person living or deceased; postage stamps or currency ..."

    reached the engine as its first line only, so a journal's prohibition
    arrived truncated mid-sentence with nothing said. Continuation lines are
    now read to the closing quote, on the same rule as the list.

    Nesting deeper than two levels is kept as its full dotted path, and also
    filed under `<group>.<leaf>`. A `statement_sections:` block under
    `structure:` was landing on `structure.<leaf>` by accident of the old
    two-level reader; now it does so on purpose, and
    `structure.statement_sections.<leaf>` names it properly.
    """
    out: dict = {}
    stack: list[tuple[int, str]] = []
    pending: tuple[str, list[str]] | None = None

    def flush() -> None:
        nonlocal pending
        if pending:
            key, items = pending
            if items:
                out[key] = "[" + ", ".join(items) + "]"
                # AND the items themselves, because the bracketed string is
                # LOSSY and a reader splitting it back on commas cannot know
                # it. A journal's own title-page list has `title and short
                # running title (46 characters or fewer, including spaces)`
                # as ONE element; joined and re-split it becomes two, and a
                # nine-line title page came out with sixteen headings on it
                # (item 129). The `[]` prefix cannot collide with a dotted
                # YAML path, which is the point of spelling it that way.
                out[LIST_ITEMS_PREFIX + key] = list(items)
            pending = None

    lines = _read(path).splitlines()
    i = 0
    while i < len(lines):
        raw = lines[i]
        opened_at = i + 1
        i += 1
        line = _strip_yaml_comment(raw).rstrip()
        if not line.strip():
            continue
        m = re.match(r"^(\s*)-\s+(.*)$", line)
        if m and pending:
            item = m.group(2).strip().strip('"').strip("'")
            if item:
                pending[1].append(item)
            continue
        flush()
        m = re.match(r"^(\s*)([A-Za-z_][\w-]*):\s*(.*)$", line)
        if not m:
            continue
        indent = len(m.group(1))
        name, val = m.group(2), m.group(3).strip()
        # An inline list wrapped over several lines. Read to the closing
        # bracket; an unclosed one is reported rather than half-read.
        if val.startswith("[") and "]" not in val:
            while i < len(lines) and "]" not in val:
                cont = _strip_yaml_comment(lines[i]).strip()
                # A line that opens a key of its own is not a continuation,
                # and stopping here is what keeps an unclosed list from
                # swallowing the rest of the file. The readers that do not ask
                # for `problems` then see exactly what they saw before.
                if re.match(r"^([A-Za-z_][\w-]*:(\s|$)|-\s)", cont):
                    break
                i += 1
                if cont:
                    val += " " + cont
            if "]" not in val and problems is not None:
                problems.append(
                    "%s line %d: the inline list for %r is never closed with "
                    "]. Everything after the line break cannot be read, so "
                    "the value is not the one written. Close the bracket, or "
                    "write it as a block list one `- item` per line."
                    % (os.path.basename(path), opened_at, name))
        # A quoted scalar wrapped over several lines. `prohibited_content` in
        # a real Langmuir requirements.yml is five lines of the journal's own
        # sentence, and only the first reached the engine - the same silent
        # truncation as the inline list above, one value shape along.
        elif val[:1] in ('"', "'") and not _quote_closed(val):
            while i < len(lines) and not _quote_closed(val):
                cont = _strip_yaml_comment(lines[i]).strip()
                # A key of its own ends it, exactly as it ends an unclosed
                # list: a missing closing quote must not swallow the file.
                if re.match(r"^([A-Za-z_][\w-]*:(\s|$)|-\s)", cont):
                    break
                i += 1
                if cont:
                    val += " " + cont
            if not _quote_closed(val) and problems is not None:
                problems.append(
                    "%s line %d: the quoted value for %r is never closed. "
                    "Everything after the line break cannot be read, so the "
                    "value is not the one written."
                    % (os.path.basename(path), opened_at, name))
        while stack and stack[-1][0] >= indent:
            stack.pop()
        key = ".".join([k for _, k in stack] + [name])
        out[key] = val.strip('"').strip("'")
        # A key nested three deep is also reachable by its first and last
        # segments, so a reader that knows `structure.funding` still finds
        # `structure.statement_sections.funding`. Langmuir's captured
        # requirements write the statements that way and the two-level reader
        # only saw them by accident.
        parts = key.split(".")
        if len(parts) > 2:
            out.setdefault(parts[0] + "." + parts[-1], out[key])
        stack.append((indent, name))
        if not val:
            pending = (key, [])
    flush()
    # A key that opened a block and got no items is still empty, not "[]".
    for k, v in list(out.items()):
        if v == "[]":
            out[k] = ""
    return out


# ---------------------------------------------------------------------------
# writing_config.yml - the dials, and the instructions you give by hand
# ---------------------------------------------------------------------------

def _unquote(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
        return value[1:-1]
    # A trailing comment is only stripped from an UNQUOTED value. An
    # instruction is free text and routinely contains a '#', so quoting has to
    # be the way to keep one.
    return value.split("#", 1)[0].strip()


def _quote(value: str) -> str:
    """Quote an instruction if it could not survive the round trip bare.

    The delimiter is chosen to suit the text rather than the text mangled to
    suit the delimiter: an instruction is the user's own words, and quietly
    turning their "novel" into 'novel' is an edit nobody asked for.
    """
    if not (any(c in value for c in "#:\"'") or value.strip() != value):
        return value
    if '"' in value and "'" not in value:
        return "'" + value + "'"
    if '"' in value and "'" in value:
        # Both quote characters are present, so neither delimiter is safe.
        # Keep the text intact and let the value stay bare - the reader only
        # strips a trailing comment, and a '#' is the one thing that would be
        # lost, so say so rather than silently truncating.
        return value.replace("#", "no. ")
    return '"' + value + '"'


def load_density(config_path: str | None,
                 problems: list[str] | None = None) -> dict:
    """`number_density` as {level, sections, waivers, problems}.

    `prose.py` owns this contract - it is the engine that resolves a budget and
    reports `budget_source` - so it is imported rather than re-implemented
    here, the same reuse `prose.py` itself makes of `learn.py`. A second copy
    of this parser is how the two engines come to disagree about what the
    user's own config says, which is the exact failure `tests/manuscript.py`
    pins with "manuscript.py and prose.py agree".
    """
    empty = {"level": None, "sections": {}, "waivers": [], "problems": []}
    if not config_path:
        return empty
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import prose as _prose_mod                  # local engine, stdlib only
    except Exception as exc:                        # pragma: no cover - import
        if problems is not None:
            problems.append(f"cannot load prose.py to read number_density: "
                            f"{exc}")
        return empty
    try:
        return _prose_mod.load_density_config(config_path)
    except Exception as exc:
        if problems is not None:
            problems.append(f"cannot read number_density from "
                            f"{os.path.basename(config_path)}: {exc}")
        return empty


def parse_config(text: str) -> dict:
    """writing_config.yml as {dials, lists, invalid, unknown}.

    A hand parser, like every other yml reader here, and list-aware: the whole
    point of custom_instructions is that a human types into it, so the block
    form has to be read as well as the inline `[]` form.
    """
    dials: dict[str, str] = {}
    lists: dict[str, list[str]] = {}
    maps: dict[str, dict] = {}
    invalid: list[str] = []
    unknown: list[str] = []
    current_list: str | None = None
    current_map: str | None = None
    # prose 5.9: `number_density` accepts a per-section mapping as well as the
    # scalar level, and the two are told apart by whether the key's own line
    # carries a value. An indented `section: value` under it is that mapping,
    # not an unknown top-level key - the top-level regex below anchors at
    # column 0, so those lines are skipped and the mapping is read separately
    # by the one parser that owns it.
    density_mapping = bool(re.search(
        r"^number_density:\s*(?:#.*)?$", text, flags=re.MULTILINE))

    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue

        item = re.match(r"^\s+-\s*(.+?)\s*$", raw)
        if item and current_list:
            lists[current_list].append(_unquote(item.group(1)))
            continue

        entry = re.match(r"^\s+([a-z_]+):\s*(.*?)\s*$", raw)
        if entry and current_map:
            maps[current_map][entry.group(1)] = _unquote(entry.group(2))
            continue

        m = re.match(r"^([a-z_]+):\s*(.*)$", raw)
        if not m:
            continue
        key, rest = m.group(1), m.group(2).strip()
        current_list = None
        current_map = None

        if key in CONFIG_MAPS:
            maps.setdefault(key, {})
            current_map = key
            continue

        if key in CONFIG_LISTS:
            lists.setdefault(key, [])
            current_list = key
            if rest.startswith("[") and rest.endswith("]"):
                inner = rest[1:-1].strip()
                if inner:
                    lists[key].extend(_unquote(v) for v in inner.split(",")
                                      if v.strip())
                current_list = None      # an inline list has no block to follow
            continue

        value = _unquote(rest)
        if key == "number_density" and not value and density_mapping:
            dials[key] = "per-section"
            continue
        if key in CONFIG_DIALS:
            dials[key] = value
            if value and value not in CONFIG_DIALS[key]:
                invalid.append(
                    f"{key}: '{value}' is not one of "
                    f"{', '.join(CONFIG_DIALS[key])} - that dial is being "
                    f"ignored, and the run is biased in a way nobody asked for")
        else:
            unknown.append(key)

    for key in CONFIG_DIALS:
        if key not in dials:
            invalid.append(f"{key}: missing from the config entirely")
    for key in ("style_refs", "custom_instructions", "number_density_waivers",
                "skip_modules", "known_abbreviations"):
        lists.setdefault(key, [])

    # A closed-set list is validated like a dial. Unrecognised members are
    # dropped rather than passed through, because the caller acts on this list
    # and a member nothing recognises would read as a scope nobody manages.
    for key, allowed in CONFIG_LIST_VALUES.items():
        if key not in lists:
            continue
        good = [v for v in lists[key] if v in allowed]
        for v in lists[key]:
            if v not in allowed:
                invalid.append(
                    f"{key}: '{v}' is not one of {', '.join(allowed)} - it is "
                    f"being ignored, so whatever it was meant to name is not "
                    f"in scope and nothing else will say so")
        lists[key] = good

    # Defaults last, so "absent" and "empty" stay distinguishable above.
    for key, default in CONFIG_LIST_DEFAULTS.items():
        lists.setdefault(key, list(default))

    # A mapping is validated like a dial and like a closed-set list: an
    # unrecognised key or level is DROPPED and reported, never passed through.
    # A weight nothing recognises would read as a source nobody ranked, and
    # `manages: [flotas]` already paid for that lesson.
    for key, entries in maps.items():
        if key != "source_weights":
            continue
        good = {}
        for name, level in entries.items():
            if name not in WEIGHTABLE_SOURCES:
                invalid.append(
                    f"source_weights: '{name}' is not a drafting source - it "
                    f"is being ignored, so whatever it was meant to weight is "
                    f"at its default. The names are: "
                    f"{', '.join(sorted(WEIGHTABLE_SOURCES))}")
                continue
            if level not in SOURCE_WEIGHT_LEVELS:
                invalid.append(
                    f"source_weights.{name}: '{level}' is not one of "
                    f"{', '.join(SOURCE_WEIGHT_LEVELS)} - it is being "
                    f"ignored, and that source is back at normal")
                continue
            # A source with only two settings says WHY the third is not one
            # of them (20.5). Reported the way a typo'd source name is -
            # dropped with the reason, never fatal - because a config that
            # refuses to load is a config nobody can fix from the message.
            allowed, why = RESTRICTED_SOURCE_WEIGHTS.get(name, (None, ""))
            if allowed and level not in allowed:
                invalid.append(
                    f"source_weights.{name}: '{level}' is not one of "
                    f"{', '.join(allowed)} - {why}. It is being ignored, so "
                    f"{name} is at {allowed[0]}")
                continue
            good[name] = level
        maps[key] = good
    for key in CONFIG_MAPS:
        maps.setdefault(key, {})

    return {"dials": dials, "lists": lists, "maps": maps,
            "invalid": invalid, "unknown": unknown}


def read_config(path: str) -> dict:
    return {**parse_config(_read(path)), "path": path}


def _set_dial(text: str, key: str, value: str) -> str:
    """Replace one dial's value, keeping its trailing comment.

    Rewriting the file from a parsed dict would drop every comment the user
    added, and this file is explicitly theirs to hand-edit.
    """
    def repl(m: re.Match) -> str:
        comment = m.group(2) or ""
        pad = " " * max(1, 31 - len(f"{key}: {value}")) if comment else ""
        return f"{key}: {value}{pad}{comment}"
    new, n = re.subn(rf"^{key}:\s*([^#\n]*)(#[^\n]*)?$", repl, text,
                     count=1, flags=re.M)
    if n:
        return new
    return text.rstrip("\n") + f"\n{key}: {value}\n"


def _list_span(lines: list[str], key: str) -> tuple[int, int] | None:
    """Line indices [start, end) covering a list key and its block items."""
    for i, line in enumerate(lines):
        if re.match(rf"^{key}:\s*", line):
            j = i + 1
            while j < len(lines) and re.match(r"^\s+-\s*", lines[j]):
                j += 1
            return i, j
    return None


def _write_list(text: str, key: str, items: list[str]) -> str:
    lines = text.splitlines()
    span = _list_span(lines, key)
    block = [f"{key}: []"] if not items else \
        [f"{key}:"] + [f"  - {_quote(i)}" for i in items]
    if span is None:
        return text.rstrip("\n") + "\n" + "\n".join(block) + "\n"
    start, end = span
    # Keep any comment that sat on the key's own line - it is usually the
    # explanation of what the list is for.
    comment = ""
    m = re.search(r"(#[^\n]*)$", lines[start])
    if m and not items:
        comment = "     " + m.group(1)
    block[0] = block[0] + comment
    return "\n".join(lines[:start] + block + lines[end:]) + "\n"


def _map_span(lines: list[str], key: str) -> tuple[int, int] | None:
    """Line indices [start, end) covering a mapping key and its entries.

    `_list_span` cannot do this job and using it was a real bug: it consumes
    `  - item` lines, so on a mapping it returned a span covering the key line
    alone. `_write_map` then inserted the new block and left the old entries
    below it - and because a later entry wins the parse, **the stale values
    survived and the new ones did not**. Measured: setting `captions: ignore`
    over `captions: primary` produced a file containing both, in that order,
    and the config read back `primary`.

    An entry is an indented line that is not a comment. A blank line or a
    dedent ends the block, which is what keeps the comment paragraph below it
    out of the span.
    """
    for i, line in enumerate(lines):
        if re.match(rf"^{key}:\s*", line):
            j = i + 1
            while j < len(lines):
                nxt = lines[j]
                if not nxt.strip():
                    break
                if not re.match(r"^\s+\S", nxt):
                    break
                if nxt.lstrip().startswith("#"):
                    break
                j += 1
            return i, j
    return None


def _write_map(text: str, key: str, entries: dict) -> str:
    """Rewrite one mapping block, keeping the key's own trailing comment.

    Same shape and the same reason as `_write_list`: rewriting the file from
    a parsed dict would drop every comment the user added, and this file is
    explicitly theirs to hand-edit.
    """
    lines = text.splitlines()
    span = _map_span(lines, key)
    block = ([f"{key}: {{}}"] if not entries else
             [f"{key}:"] + [f"  {k}: {v}" for k, v in sorted(entries.items())])
    if span is None:
        return text.rstrip("\n") + "\n" + "\n".join(block) + "\n"
    start, end = span
    comment = ""
    m = re.search(r"(#[^\n]*)$", lines[start])
    if m and not entries:
        comment = "     " + m.group(1)
    block[0] = block[0] + comment
    return "\n".join(lines[:start] + block + lines[end:]) + "\n"

def waive_outline_line(project: str, target: str, because: str) -> dict:
    """Mark one outline line `[waived: reason]` (prose 4.4).

    The third state the toolkit lacked. `**[FLAG]**` can only say "absent,
    someone must fill it"; a deliberate deletion needs "absent on purpose,
    stop asking", and without it an advisory-once finding is still a report
    every round forever.

    `target` is `<section>:<line>` - the line number `prose.py outline`
    reports, which is why it is a line number and not a fuzzy text match: the
    user is looking at that report when they decide to settle a line, and
    matching on claim text would waive the wrong line the round someone
    rewords one.
    """
    path = os.path.join(project, "plan", "outline.md")
    if not os.path.isfile(path):
        return {"errors": [f"no outline at {path}"], "changes": []}
    if not str(because or "").strip():
        return {"errors": [
            "--waive-outline needs --because. The reason is the whole point "
            "of the marker: an unexplained waiver is the thing nobody can "
            "audit in six months, and a line waived without one is "
            "indistinguishable from a line someone deleted by accident"],
            "changes": []}
    m = re.match(r"^\s*([A-Za-z_ ]*?)\s*:\s*(\d+)\s*$", target)
    if not m:
        return {"errors": [
            f"--waive-outline expects <section>:<line>, got '{target}'. The "
            f"line number is the one `prose.py outline` reports, e.g. "
            f"methods:14"], "changes": []}
    want_section, want_line = m.group(1).strip().lower(), int(m.group(2))

    raw = _read(path)
    lines = raw.splitlines(keepends=True)
    if not 1 <= want_line <= len(lines):
        return {"errors": [
            f"outline.md has {len(lines)} lines; there is no line "
            f"{want_line}"], "changes": []}
    original = lines[want_line - 1]
    lm = re.match(r"^([-*]\s+)(.*\S)\s*$", original.rstrip("\r\n"))
    if not lm:
        return {"errors": [
            f"outline.md:{want_line} is not an outline line - it is "
            f"{original.strip()[:60]!r}. Waiving anything else would put a "
            f"marker where nothing reads it"], "changes": []}
    body = lm.group(2)
    if re.match(r"^\[waived\b", body, re.IGNORECASE):
        return {"errors": [], "changes": [],
                "note": f"outline.md:{want_line} is already waived"}

    # The section is checked rather than used, so a mistyped line number that
    # happens to be a valid outline line in a DIFFERENT section is caught
    # before it silently settles the wrong point.
    if want_section:
        seen = ""
        for line in lines[:want_line]:
            sm = re.match(r"^#{1,6}\s+(.*\S)\s*$", line)
            if sm:
                seen = sm.group(1).strip().lower()
        if seen and want_section not in seen and seen not in want_section:
            return {"errors": [
                f"outline.md:{want_line} is under '{seen}', not "
                f"'{want_section}'. Nothing was changed - a line number off "
                f"by a few settles a point you meant to keep"],
                "changes": []}

    eol = original[len(original.rstrip("\r\n")):]
    reason = " ".join(str(because).split()).replace("]", ")")
    lines[want_line - 1] = f"{lm.group(1)}[waived: {reason}] {body}{eol}"
    _write(path, "".join(lines))
    return {"errors": [], "changes": [
        {"key": "outline", "action": "waive",
         "detail": f"outline.md:{want_line} - {body[:60]} - not drafted, not "
                   f"reported as uncovered, not counted in adherence. "
                   f"Because: {reason}"}]}


def set_research_type(project: str, type_id: str) -> dict:
    """Cache the research type in project.yml (prose 5.5).

    Asked once, cached, never re-asked; changed only by an explicit flag, and
    the change is logged because the layer-3 brief changes with it. The
    vocabulary is `learn.py`'s and is checked against it here rather than
    copied - a type this engine accepted and that one did not would scope a
    rule to a population of zero, silently.
    """
    ypath = os.path.join(project, "project.yml")
    known: list[dict] = []
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import learn as _learn                      # local engine, stdlib only
        known = _learn.read_types()
    except Exception as exc:                        # pragma: no cover - import
        return {"errors": [f"cannot read the research-type vocabulary: {exc}"],
                "changes": []}
    ids = [t["id"] for t in known]
    if type_id not in ids:
        return {"errors": [
            f"'{type_id}' is not in the research-type vocabulary. The types "
            f"are {', '.join(ids)}. Adding one is deliberate and needs a "
            f"reason: `learn.py types --add <id> --label \"...\" "
            f"--because \"...\"`"], "changes": []}
    before = read_project_yml(project).get("research_type", "").strip()
    if before == type_id:
        return {"errors": [], "changes": [],
                "note": f"research_type is already {type_id}"}
    raw = _read(ypath)
    if not raw:
        return {"errors": [f"no project.yml at {ypath}"], "changes": []}
    line = f"research_type: {type_id}"
    m = re.search(r"^research_type:.*$", raw, re.M)
    if m:
        raw = raw[:m.start()] + line + raw[m.end():]
    else:
        m2 = re.search(r"^target_journal:.*$", raw, re.M)
        if m2:
            raw = raw[:m2.end()] + "\n" + line + raw[m2.end():]
        else:
            raw = raw.rstrip("\n") + "\n" + line + "\n"
    _write(ypath, raw)
    return {"errors": [], "changes": [
        {"key": "research_type", "action": "set",
         "detail": f"{before or '(unset)'} -> {type_id}; the layer-3 drafting "
                   f"brief changes with it, and rules learned under "
                   f"{before or 'no type'} stay scoped to it"}]}


def set_paper_kind(project: str, kind: str | None,
                   rkind: str | None = None) -> dict:
    """Record what this document IS in project.yml (review-paper 1).

    A real event, and reported as one: the section stems, the layer-0 rule,
    the module list, the density budget and the scope set all branch on it,
    and a paper kind changed quietly between rounds would change every one
    of them with nothing in the run log saying why.

    It does not move a file. Converting a research project into a review
    means building a corpus, and this writes the key that makes the rest of
    the engine ask for one.
    """
    ypath = os.path.join(project, "project.yml")
    changes: list[dict] = []
    notes: list[str] = []
    if kind and kind not in PAPER_KINDS:
        return {"errors": [f"'{kind}' is not a paper kind. The kinds are "
                           f"{', '.join(PAPER_KINDS)}."], "changes": []}
    if rkind and rkind not in REVIEW_KINDS:
        return {"errors": [f"'{rkind}' is not a review kind. The kinds are "
                           f"{', '.join(REVIEW_KINDS)}."], "changes": []}
    raw = _read(ypath)
    if not raw:
        return {"errors": [f"no project.yml at {ypath}"], "changes": []}

    def put(key: str, value: str, after: str) -> None:
        nonlocal raw
        m = re.search(r"^%s:.*$" % re.escape(key), raw, re.M)
        line = f"{key}: {value}"
        if m:
            raw = raw[:m.start()] + line + raw[m.end():]
            return
        m2 = re.search(r"^%s:.*$" % re.escape(after), raw, re.M)
        if m2:
            raw = raw[:m2.end()] + "\n" + line + raw[m2.end():]
        else:
            raw = raw.rstrip("\n") + "\n" + line + "\n"

    before_kind = paper_kind(project)
    before_rkind = str(read_project_yml(project).get("review_kind", "")).strip()
    if kind and kind != before_kind:
        put("paper_kind", kind, "title")
        changes.append({
            "key": "paper_kind", "action": "set",
            "detail": f"{before_kind} -> {kind}; the section stems, the "
                      f"layer-0 rule, the module list, the density budget "
                      f"and the managed scopes all change with it"})
    elif kind:
        changes.append({"key": "paper_kind", "action": "keep",
                        "detail": f"already {kind}"})
    if rkind and rkind != before_rkind:
        put("review_kind", rkind, "paper_kind")
        reports = rkind in REVIEW_KINDS_REPORTING
        changes.append({
            "key": "review_kind", "action": "set",
            "detail": f"{before_rkind or '(unset)'} -> {rkind}; the search "
                      f"record is written either way and is "
                      f"{'reported as a Methods section' if reports else 'kept as provenance in data/corpus/'}"})
        if reports:
            # Reported HERE and at the first corpus build, never at
            # submission: registration is the one requirement whose lateness
            # cannot be repaired, and news of it at submission is useless
            # (review-paper 14).
            notes.append(
                "registration is a PRE-registration: PROSPERO and its "
                "equivalents cannot be applied for after screening has "
                "started, so if this review needs one it needs one now. "
                "Record the answer in data/corpus/protocol.md.")
    if any(c["action"] == "set" for c in changes):
        _write(ypath, raw)
    return {"errors": [], "notes": notes, "changes": changes}


def configure(project: str, journal: str, sets: list[str] | None = None,
              instruct: list[str] | None = None,
              style_ref: list[str] | None = None,
              waive: list[str] | None = None,
              forget: list[str] | None = None, skip: list[str] | None = None,
              manages: list[str] | None = None,
              weight: list[str] | None = None,
              forget_weight: list[str] | None = None,
              dated: bool = True, dry_run: bool = False) -> dict:
    """Read the config, and apply any changes asked for, in place.

    Instructions accumulate: the spec's requirement is that free text given at
    any invocation persists into later rounds, so this appends rather than
    replaces, and `--forget` is the only way one leaves.
    """
    jdir = journal_dir(project, journal)
    path = os.path.join(jdir, "writing_config.yml")
    if not os.path.isfile(path):
        return {"errors": [f"no writing_config.yml at {path}; run init first"],
                "changes": []}

    text = _read(path)
    before = read_config(path)
    changes: list[dict] = []
    errors: list[str] = []

    for pair in sets or []:
        if "=" not in pair:
            errors.append(f"--set expects key=value, got '{pair}'")
            continue
        key, value = (s.strip() for s in pair.split("=", 1))
        if key not in CONFIG_DIALS:
            errors.append(f"'{key}' is not a dial; the dials are "
                          f"{', '.join(sorted(CONFIG_DIALS))}")
            continue
        if value not in CONFIG_DIALS[key]:
            errors.append(f"{key}: '{value}' is not one of "
                          f"{', '.join(CONFIG_DIALS[key])}")
            continue
        old = before["dials"].get(key, "")
        if old != value:
            text = _set_dial(text, key, value)
            detail = f"{old or '(unset)'} -> {value}"
            if key == "audience":
                # A real event, the same way research_type is. The next
                # comprehension report will differ for a reason that has
                # nothing to do with the prose, and a reader who does not
                # know the yardstick moved will read that as the paper
                # getting harder (comprehension-check 4).
                detail += ("; comprehension-check is asked to be a "
                           "different reader from now on, so its next "
                           "report differs for a reason that is not about "
                           "the prose")
            changes.append({"key": key, "action": "set", "detail": detail})

    # A module name is the one list entry with a right answer, so it is checked
    # before it is written. A typo recorded here would be a standing
    # preference that silently never applies.
    valid_skips: list[str] = []
    for m in skip or []:
        m = m.strip()
        if m in MODULES:
            valid_skips.append(m)
        elif m:
            errors.append(f"'{m}' is not a module; the modules are "
                          f"{', '.join(MODULES)}")

    additions = [("custom_instructions", instruct or [], dated),
                 ("style_refs", style_ref or [], False),
                 ("number_density_waivers", waive or [], False),
                 ("skip_modules", valid_skips, False)]
    for key, values, stamp in additions:
        if not values:
            continue
        items = list(parse_config(text)["lists"].get(key, []))
        for v in values:
            v = v.strip()
            if not v:
                continue
            entry = f"{TODAY}: {v}" if stamp else v
            # Compare on the text after any date stamp, so re-giving the same
            # instruction in a later round is a no-op rather than a duplicate.
            if any(i.split(": ", 1)[-1] == v for i in items):
                changes.append({"key": key, "action": "keep",
                                "detail": f"already recorded: {v}"})
                continue
            items.append(entry)
            text = _write_list(text, key, items)
            changes.append({"key": key, "action": "add", "detail": entry})

    # `manages` REPLACES rather than accumulates, and that is the difference
    # that matters: every other list here is "one more thing to remember", and
    # this one is a complete statement of what the project holds. Appending to
    # it would make "we moved the figures out" impossible to say.
    #
    # `--manages none` is spelled out rather than inferred from an empty
    # argument, because an empty list here is a real and consequential value
    # (a manuscript-only project) and a shell that swallows an argument must
    # not be able to produce it by accident.
    if manages is not None:
        raw = [v.strip() for item in manages for v in item.split(",")]
        raw = [v for v in raw if v]
        if [v.lower() for v in raw] == ["none"]:
            wanted: list[str] = []
        else:
            wanted = []
            for v in raw:
                if v in MANAGED_SCOPES:
                    if v not in wanted:
                        wanted.append(v)
                else:
                    errors.append(
                        f"'{v}' is not a scope; the scopes are "
                        f"{', '.join(MANAGED_SCOPES)} (or `none` for a "
                        f"manuscript-only project)")
        if not errors:
            old = before["lists"].get("manages", list(MANAGED_SCOPES))
            ordered = [s for s in MANAGED_SCOPES if s in wanted]
            if ordered != old:
                text = _write_list(text, "manages", ordered)
                changes.append({
                    "key": "manages", "action": "set",
                    "detail": f"{', '.join(old) or '(nothing)'} -> "
                              f"{', '.join(ordered) or '(nothing)'}"})
            else:
                changes.append({"key": "manages", "action": "keep",
                                "detail": f"already {', '.join(old) or '(nothing)'}"})

    # --- source_weights (spec 16.2) ---------------------------------------
    #
    # A weight is instruction text in a brief, never a change to what a module
    # is GIVEN - the given/denied lists are the isolation contract. The one
    # exception is `ignore`, which removes the file and says so.
    wanted_weights = dict(before["maps"].get("source_weights", {}))
    touched_weights = False
    for pair in weight or []:
        if "=" not in pair:
            errors.append(f"--weight expects source=level, got '{pair}'")
            continue
        name, level = (x.strip() for x in pair.split("=", 1))
        if name not in WEIGHTABLE_SOURCES:
            errors.append(
                f"'{name}' is not a drafting source; the weightable sources "
                f"are {', '.join(sorted(WEIGHTABLE_SOURCES))}")
            continue
        if level not in SOURCE_WEIGHT_LEVELS:
            errors.append(f"{name}: '{level}' is not one of "
                          f"{', '.join(SOURCE_WEIGHT_LEVELS)}")
            continue
        allowed, why = RESTRICTED_SOURCE_WEIGHTS.get(name, (None, ""))
        if allowed and level not in allowed:
            errors.append(f"{name}: '{level}' is not one of "
                          f"{', '.join(allowed)} - {why}")
            continue
        old_level = wanted_weights.get(name, "normal")
        if old_level == level:
            changes.append({"key": "source_weights", "action": "keep",
                            "detail": f"{name} is already {level}"})
            continue
        wanted_weights[name] = level
        touched_weights = True
        changes.append({"key": "source_weights", "action": "set",
                        "detail": f"{name}: {old_level} -> {level}"})
    for name in forget_weight or []:
        name = name.strip()
        if name in wanted_weights:
            changes.append({"key": "source_weights", "action": "drop",
                            "detail": f"{name} back to normal "
                                      f"(was {wanted_weights[name]})"})
            wanted_weights.pop(name)
            touched_weights = True
        else:
            errors.append(f"no weight is set for '{name}'")
    if touched_weights and not errors:
        text = _write_map(text, "source_weights", wanted_weights)

    for target in forget or []:
        for key in ("custom_instructions", "style_refs",
                    "number_density_waivers", "skip_modules"):
            items = list(parse_config(text)["lists"].get(key, []))
            hit = [i for i in items
                   if target.strip().lower() in i.lower()]
            if not hit:
                continue
            for h in hit:
                items.remove(h)
                changes.append({"key": key, "action": "drop", "detail": h})
            text = _write_list(text, key, items)
            break
        else:
            errors.append(f"nothing in the config matches '{target}'")

    if changes and not dry_run:
        _write(path, text)

    after = {**parse_config(text), "path": path}
    return {"project": os.path.abspath(project), "journal": journal,
            "paper_kind": paper_kind(project),
            "config": after, "changes": changes, "errors": errors,
            "dry_run": dry_run}


# --- LAYOUT CONTRACT (verbatim in manuscript.py, prose.py, toc_graphic.py) ---
# Every command in this toolkit is standalone by design, so this resolver is
# repeated rather than imported, exactly like CAPTION_HEADING_RE.
# `tests/prose.py` compares the three byte for byte. Edit one, edit all three.

# What makes a folder a journal folder rather than a sibling of one. Any of
# these is enough: writing_config.yml is written by `init`, and the other two
# survive a project whose config was deleted or never committed.
JOURNAL_MARKERS = ("writing_config.yml", "journal_requirements", "edits")

# The live source text carries the round it holds: `source_text_r8`.
#
# One counter runs across every journal in a project (item 18), so a LANGMUIR
# folder that stopped at r5 can sit beside source text that has moved on to
# r8, and nothing on disk said so: `source_text/` looked the same on the day
# r5 was sent and on the day r8 was drafted. The label is the whole answer -
# `manuscript_r5.docx` next to `source_text_r8/` is visibly not what would
# build today.
#
# An unsuffixed `source_text/` is the layout that predates the label and is
# still read. `init` and `round` rename it forward rather than leaving two,
# because two folders holding a manuscript is the one thing this resolver has
# never been able to answer.
SOURCE_TEXT_RE = re.compile(r"^source_text(?:_r(\d+))?$")


def source_text_label(rnd: int) -> str:
    """The folder name for a given round; 0 means no round is known yet."""
    return "source_text_r%d" % rnd if rnd and rnd > 0 else "source_text"


def source_text_folders(d: str) -> list[tuple[int, str]]:
    """(round, name) for every source_text folder in `d`, oldest first.

    The unsuffixed one sorts as round 0: it predates the label, so any folder
    carrying one is newer than it. Callers take the LAST, never the first - a
    project part-way through the rename holds both, and the newest is live.
    """
    out: list[tuple[int, str]] = []
    if not os.path.isdir(d):
        return out
    for name in os.listdir(d):
        m = SOURCE_TEXT_RE.match(name)
        if m and os.path.isdir(os.path.join(d, name)):
            out.append((int(m.group(1) or 0), name))
    return sorted(out)


def _looks_like_journal(path: str) -> bool:
    return any(os.path.exists(os.path.join(path, m)) for m in JOURNAL_MARKERS)


def _is_drafting_folder(d: str) -> bool:
    """Does this directory hold a manuscript, rather than merely a folder?

    Two independent marks, because either can outlive the other. Written
    sections are the obvious one. A journal folder is the one that matters
    after a clean slate: a trimmed project whose prose has been deleted so the
    skill can redraft it still has `Langmuir/`, and without this second mark
    the project would silently flip back to expecting `drafts/` at the exact
    moment it was emptied - and the redraft would land somewhere else.

    An empty `source_text*/` with no journal beside it is deliberately NOT a
    drafting folder. Nothing has been created there yet, so it is scaffolded
    like any other bare directory.
    """
    if not os.path.isdir(d):
        return False
    for _rnd, name in source_text_folders(d):
        st = os.path.join(d, name)
        if any(f.endswith(".md") for f in os.listdir(st)):
            return True
    return any(_looks_like_journal(os.path.join(d, x))
               for x in os.listdir(d) if os.path.isdir(os.path.join(d, x)))


def drafts_dir(project: str) -> str:
    """The folder holding source_text/, the journal folders and the .bib.

    In a full project that is `drafts/`. In a **trimmed** project - source_text/
    plus a journal folder, with data and figures managed elsewhere (spec 7.2.2)
    - the project root IS the drafting folder and there is no drafts/ wrapper.
    That layout was supported here and in toc_graphic.py but hard-refused by
    manuscript.py and prose.py at 33 sites, which is why `status` on a real
    trimmed project reported five empty sections while 5262 words sat one
    directory up. A wrong answer at exit 0 is worse than the refusal it
    replaced.

    Resolution is by content, never by the folder name: the wrapper can be
    called anything (`manuscript/` is what the first real project used). When
    neither location holds a manuscript nothing has been created yet, so
    `drafts/` is returned as the layout `init` will build.
    """
    full = os.path.join(project, "drafts")
    if _is_drafting_folder(full):
        return full
    if _is_drafting_folder(project):
        return project
    return full


def is_trimmed(project: str) -> bool:
    """True when the project root is its own drafting folder (no drafts/)."""
    return os.path.abspath(drafts_dir(project)) == os.path.abspath(project)


def dpfx(project: str) -> str:
    """The `drafts/` prefix as it should appear in a message, or "".

    Every message naming a file the user is meant to open has to name the path
    they will actually find it at. A trimmed project told to edit
    `drafts/source_text/results.md` is sent looking for a folder that is not
    there, and a path that is wrong in a diagnostic is worse than no path at
    all - it is the diagnostic they will trust.
    """
    return "" if is_trimmed(project) else "drafts/"


def source_text_name(project: str) -> str:
    """The live source_text folder's own name, round label and all.

    The newest label wins. Nothing at all means nothing has been created here
    yet, and the unsuffixed name is what a caller would build - the same rule
    `drafts_dir` applies when neither location holds a manuscript.
    """
    found = source_text_folders(drafts_dir(project))
    return found[-1][1] if found else "source_text"


def source_text_dir(project: str) -> str:
    return os.path.join(drafts_dir(project), source_text_name(project))


def stpfx(project: str) -> str:
    """The live source_text folder as it should appear in a message.

    `drafts/source_text_r8/` in a full project, `source_text_r8/` in a trimmed
    one. Every diagnostic naming a file inside it runs through this, for the
    reason `dpfx` exists one line up: once the folder carries a round label
    there is no `source_text/` to open, and a path that is wrong in a
    diagnostic is worse than no path at all.
    """
    return dpfx(project) + source_text_name(project) + "/"


# The inbox is the PROJECT's, and since 2026-09-24 it sits beside source_text/
# rather than inside the journal folder: `drafts/edits/`.
#
# It moved because of what a coauthor actually does. They are sent a manuscript
# and they send one back, into whatever folder they were pointed at last time.
# Nobody outside the project knows or cares which journal this round is aimed
# at, and a return dropped in `drafts/IJROBP/edits/` after the paper moved to
# Langmuir is a file `ingest` does not read and nothing reports as missing.
# `retire-journal` carried a whole refusal path to walk the ledger across that
# boundary by hand; one inbox a level up makes the boundary disappear.
#
# THE PER-JOURNAL LOCATION IS STILL READ, AND IS MOVED FOR NOBODY. A project
# that already has `drafts/<Journal>/edits/` keeps using it - the same
# read-only rule the front-matter move follows (`front_matter_candidates`).
# `ingest` matches a return against the fingerprint the last round wrote, and
# an inbox that relocates under a round part-way through ingest loses that
# match. New projects and new journal folders get the new place.
EDITS_FOLDER = "edits"


def edits_dir(jdir: str) -> str:
    """The inbox for the project this journal folder belongs to.

    Takes the JOURNAL folder rather than the project, because that is what
    every caller already has in hand and because the older location is a child
    of it - one resolves from the other with no second argument to get wrong.
    """
    old = os.path.join(jdir, EDITS_FOLDER)
    if os.path.isdir(old):
        return old
    return os.path.join(os.path.dirname(os.path.normpath(jdir)), EDITS_FOLDER)


def edits_pfx(project: str, jdir: str) -> str:
    """The inbox as it should appear in a message, project-relative.

    `drafts/edits/` in a new project, `drafts/IJROBP/edits/` in one that
    predates the move, `edits/` in a trimmed one. Every diagnostic naming a
    file in the inbox runs through this, for the reason `dpfx` and `stpfx`
    exist above: a path that is wrong in a diagnostic is worse than no path at
    all - it is the diagnostic they will trust.
    """
    rel = os.path.relpath(edits_dir(jdir), project).replace(os.sep, "/")
    return rel + "/"


def bib_path(project: str) -> str:
    return os.path.join(drafts_dir(project), "references.bib")
# --- END LAYOUT CONTRACT ----------------------------------------------------


# A journal folder may not be named like a round. `obsolete/drafts/` holds
# both `rN/` round folders and `<JOURNAL>/` retired-journal folders since
# round-archive 4, and this function uppercases a bare lowercase name - so a
# journal abbreviated `r2` becomes `R2`, which on Windows and on OneDrive is
# the SAME directory as the round folder `r2`. The round's snapshot and the
# retired journal would then land on top of each other, silently.
#
# Two lines for a case that will probably never occur, and it is here because
# "a lookup that is almost right is the recurring bug" is this toolkit's most
# expensive class and a case-folding collision is the quietest member of it.
JOURNAL_ROUND_RE = re.compile(r"^[rR]\d+$")


def _clean_journal_name(name: str) -> str:
    clean = re.sub(r'[\\/:*?"<>|]+', "", (name or "").strip())
    return re.sub(r"\s+", "_", clean)


def journal_name_refusal(name: str) -> str:
    """Why this journal name cannot be a folder, or "" when it can.

    Separate from `journal_folder` so a command can report the refusal in its
    `errors` list - the shape every refusal in this engine takes - rather
    than letting an exception reach the console as a traceback.
    """
    clean = _clean_journal_name(name)
    if JOURNAL_ROUND_RE.match(clean):
        return ("%s cannot be a journal folder: rN is what a ROUND folder is "
                "called, and obsolete/drafts/ holds both. On Windows and on "
                "OneDrive %s/ and %s/ are the same directory, so the retired "
                "journal and that round's snapshot would land on top of each "
                "other. Use the journal's own abbreviation."
                % (clean, clean.upper(), clean.lower()))
    if clean.lower() == EDITS_FOLDER:
        return ("%s cannot be a journal folder: the inbox is a SIBLING of the "
                "journal folders now, at %s/, and on Windows and on OneDrive "
                "%s/ and %s/ are the same directory. A journal folder here "
                "would be scaffolded straight on top of what coauthors return "
                "into. Use the journal's own abbreviation."
                % (clean, EDITS_FOLDER, clean.upper(), clean.lower()))
    return ""


def journal_folder(name: str) -> str:
    """The folder name for a target journal.

    Deliberate exception to the snake_case rule (spec 2.1): journal
    abbreviations are proper nouns with established capitalization, and
    drafts/ijrobp/ looks wrong to every coauthor who opens the folder. Slashes
    and spaces are still stripped. The abbreviation itself is the skill's to
    supply - abbreviating "Nature Communications" to "Nat_Commun" is knowledge,
    not string manipulation, so this only cleans what it is given.

    Raises ValueError on a round-shaped name, which is the one case where
    returning a folder is worse than refusing - see JOURNAL_ROUND_RE. Every
    route the user's own text takes into here is guarded in `main`, and
    `existing_journals` skips such a folder, so the raise is not reachable by
    reading a directory.
    """
    clean = _clean_journal_name(name)
    if JOURNAL_ROUND_RE.match(clean):
        raise ValueError(journal_name_refusal(name))
    if clean and clean == clean.lower() and "_" not in clean:
        clean = clean.upper()
    return clean or "JOURNAL"


def journal_dir(project: str, journal: str) -> str:
    return os.path.join(drafts_dir(project), journal_folder(journal))


def existing_journals(project: str) -> list[str]:
    d = drafts_dir(project)
    if not os.path.isdir(d):
        return []
    # A trimmed project's root holds more than journal folders - source_text/,
    # toc_graphic/, whatever else the paper keeps beside them - so a journal is
    # recognised by what it contains rather than by being a directory here.
    # A round-shaped folder is skipped rather than raised on: `journal_folder`
    # refuses one, and a directory read must not be the thing that discovers
    # it. No folder here can have been made by this engine with such a name
    # since round-archive 6, so skipping loses nothing that was ever a journal.
    #
    # `edits/` is excluded by name. Nothing in it trips `_looks_like_journal`
    # today, but the inbox is a sibling of the journal folders now rather than
    # a child of one, and a marker list that grows into it would turn the
    # project's inbox into a journal called EDITS - which `init` would then
    # scaffold a manuscript into.
    return sorted(x for x in os.listdir(d)
                  if os.path.isdir(os.path.join(d, x))
                  and x != EDITS_FOLDER
                  and not SOURCE_TEXT_RE.match(x)
                  and not JOURNAL_ROUND_RE.match(x)
                  and _looks_like_journal(os.path.join(d, x)))


def stale_source_text(project: str) -> list[str]:
    """Every source_text folder holding prose that is NOT the live one.

    The label gives a total order, so unlike the drafts/-versus-root case
    there is an answer here and the newest is it - keeping r5 beside r8 as a
    record is a legitimate thing to do. What is not legitimate is doing it
    silently: prose in a folder nothing builds from is the exit-code-0 failure
    this engine keeps having to be taught not to produce, so every command
    that reads the manuscript names them.
    """
    d = drafts_dir(project)
    found = source_text_folders(d)
    out = []
    for _rnd, name in found[:-1]:
        if any(x.endswith(".md") and _read(os.path.join(d, name, x)).strip()
               for x in os.listdir(os.path.join(d, name))):
            out.append(name)
    return out


def label_source_text(project: str, rnd: int,
                      dry_run: bool = False) -> dict | None:
    """Rename the live source_text folder to the round it now holds.

    Called by the two commands that move the counter - `init`, when a new
    journal opens the next round, and `round`, when one closes. Nothing else
    renames it: the label has to mean "the round this text belongs to", and a
    folder renamed by a command that did not move the counter would say
    something the counter does not.

    Returns the action to report, or None when the name is already right.

    A destination that already exists is left alone and reported rather than
    merged - merging two folders of prose is not this function's call, and
    `stale_source_text` is what names the one left behind. Going forward that
    case cannot arise, because the newest label is what resolves as live; it
    is reachable the other way, when `rnd` is BEHIND a folder already on disk
    (a hand-edited `round_state.json`, an interrupted run), and there
    `os.rename` would otherwise raise rather than say anything useful.
    """
    if not rnd or rnd < 1:
        return None
    d = drafts_dir(project)
    found = source_text_folders(d)
    if not found:
        return None
    was = found[-1][1]
    now = source_text_label(rnd)
    if was == now:
        return None
    dest = os.path.join(d, now)
    if os.path.exists(dest):
        return {"action": "keep", "path": dpfx(project) + was,
                "detail": f"not renamed to {now}/ - that folder already "
                          f"exists. Merge them by hand; every module builds "
                          f"from {now}/"}
    if not dry_run:
        os.rename(os.path.join(d, was), dest)
    return {"action": "rename", "path": dpfx(project) + now,
            "detail": f"was {was}/ - the label is the round the source text "
                      f"holds, so a journal folder left at an earlier rN is "
                      f"visibly not what would build today"}


# The round counter is state, not an inference from the filenames, and that
# is the correction of a real bug. Read off the .docx names alone, the highest
# built file WAS the current round, so `assemble` had to build N+1 - and every
# rebuild inside one round opened a new one. Iterating on a single draft left
# manuscript_r1 through _r5 in the folder while run_state.json, reports/r1/
# and log.md all still said r1, and `status` then reported round 5. The audit
# trail split in two: the reports described a build whose filename was gone.
#
# `round` is the only command that advances the counter, so `round` is what
# records it. The folder is still read as well, and deliberately: a manuscript
# built before this file existed, or one left by a hand that deleted it, is
# evidence about the counter that must not be thrown away.
ROUND_STATE = "round_state.json"

MANUSCRIPT_RE = re.compile(r"^manuscript_r(\d+)(_MOCK)?\.docx$")


def submission_dir(project: str, journal: str) -> str:
    """Where the live round's artefacts live: the manuscript and its package.

    The journal folder root used to hold `manuscript_rN.docx` for every round
    while the folder named for the thing that is sent stood empty, so "what
    goes to the journal right now" had no single answer in the folder and by
    r5 it had five. The rule now is that the journal folder holds the LIVE
    round and the standing files, and everything else is that round's record,
    retired whole by `round` into `obsolete/drafts/rN/` (item 17).
    """
    return os.path.join(journal_dir(project, journal), "submission")


def project_of(jdir: str) -> str:
    """The project root a journal folder belongs to.

    The round counter is the project's now rather than the folder's (item 18),
    and the dozen functions that read it are called with the journal folder
    alone. Rather than thread the project through all of them it is recovered
    here: a journal folder sits directly under the drafting folder, which is
    either `<project>/drafts` or - in a trimmed project - `<project>` itself.
    Where neither carries a project.yml the answer is the folder's parent,
    which is what the counter read before this and so loses nothing.
    """
    parent = os.path.dirname(os.path.abspath(jdir))
    if os.path.isfile(os.path.join(parent, "project.yml")):
        return parent
    up = os.path.dirname(parent)
    if os.path.isfile(os.path.join(up, "project.yml")):
        return up
    return parent


def project_revision(project: str) -> int:
    """`project.yml:revision` - the project's round counter, or 0 if absent."""
    raw = read_project_yml(project).get("revision", "").strip()
    return int(raw) if raw.isdigit() else 0


def set_project_revision(project: str, value: int) -> bool:
    """Move the counter. False when there is no key to move."""
    ypath = os.path.join(project, "project.yml")
    raw = _read(ypath)
    m = re.search(r"^revision:\s*(\d+)\s*$", raw, re.M)
    if not m:
        return False
    _write(ypath, raw[:m.start()] + "revision: %d" % value + raw[m.end():])
    return True


ROUNDS_LEDGER_HEAD = ("rounds:                          "
                      "# which journal each round belonged to")


def rounds_ledger(project: str) -> list[tuple[int, int, str]]:
    """The `rounds:` block of project.yml as (first, last, journal) runs."""
    raw = _read(os.path.join(project, "project.yml"))
    m = re.search(r"^rounds:[^\n]*\n((?:[ \t]+\S[^\n]*\n?)*)", raw, re.M)
    out: list[tuple[int, int, str]] = []
    for line in (m.group(1).splitlines() if m else []):
        hit = re.match(r"^\s*r(\d+)(?:-r?(\d+))?:\s*(\S.*?)\s*$", line)
        if hit:
            first = int(hit.group(1))
            out.append((first, int(hit.group(2) or first), hit.group(3)))
    return out


def recorded_rounds(project: str) -> dict[int, str]:
    """Which journal owned each round, out of `project.yml:rounds`.

    The read side of `record_round_journal`, and the reason it has one is
    round-archive 4.3(a): `retire-journal` moves a journal folder out of
    `drafts/`, so `existing_journals` stops seeing it and the round counter
    falls back to `project_revision` - which is the round LANGMUIR is still
    sitting on, not the next one. JPCC then reuses r7 and the project has two
    `manuscript_r7.docx` meaning different things, which is item 18's defect
    returning through a folder move.

    This ledger is the only one of the three sources a directory move cannot
    invalidate, so reading it makes the retirement order stop mattering -
    which is the property to want. "Retire after init, never before" is a
    thing someone has to remember, and the counter design exists because a
    folder-derived counter was wrong.
    """
    out: dict[int, str] = {}
    for first, last, jrn in rounds_ledger(project):
        for r in range(first, last + 1):
            out[r] = jrn
    return out


def record_round_journal(project: str, rnd: int, journal: str) -> bool:
    """Note that round `rnd` belongs to `journal`, in project.yml.

    The project-level history that did not exist: each `log.md` was headed
    with its own journal, so the journal of a round was recoverable only if
    you already knew which file to open. With one counter across journals a
    bare `r8` in a folder that also holds r1-r7 stops being self-explanatory,
    and this is the thing that answers "when did we switch" (item 18).
    """
    folder = journal_folder(journal)
    # Expanded to one entry per round before the write, then re-run. Editing
    # the ranges in place dropped every other round in the range the new one
    # fell inside: recording r2 into `r1-r2` deleted the run and left `r2`.
    owner: dict[int, str] = {}
    for first, last, jrn in rounds_ledger(project):
        for r in range(first, last + 1):
            owner[r] = jrn
    owner[rnd] = folder
    merged: list[list] = []
    for r in sorted(owner):
        if merged and merged[-1][2] == owner[r] and merged[-1][1] + 1 == r:
            merged[-1][1] = r
        else:
            merged.append([r, r, owner[r]])
    lines = ["  r%d: %s" % (f, j) if f == last_
             else "  r%d-r%d: %s" % (f, last_, j)
             for f, last_, j in merged]
    body = ROUNDS_LEDGER_HEAD + "\n" + "\n".join(lines) + "\n"

    ypath = os.path.join(project, "project.yml")
    raw = _read(ypath)
    if not raw:
        return False
    m = re.search(r"^rounds:[^\n]*\n(?:[ \t]+\S[^\n]*\n?)*", raw, re.M)
    if m:
        _write(ypath, raw[:m.start()] + body + raw[m.end():])
        return True
    # Under `revision:`, which is the counter these lines annotate.
    anchor = re.search(r"^revision:[^\n]*\n", raw, re.M)
    at = anchor.end() if anchor else len(raw)
    _write(ypath, raw[:at] + body + raw[at:])
    return True


def round_state(jdir: str) -> dict:
    """What `round` last recorded here, or {} if it has never run."""
    try:
        data = json.loads(_read(os.path.join(jdir, ROUND_STATE)) or "{}")
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def update_round_state(jdir: str, **fields) -> dict:
    """Merge into round_state.json rather than replacing it.

    It carries three unrelated things now - the open round, which rounds this
    folder owns, and the SHA-256 of what the last build wrote (item 8) - and
    a wholesale rewrite by any one of their writers would drop the other two.
    """
    state = round_state(jdir)
    state.update(fields)
    _write(os.path.join(jdir, ROUND_STATE), json.dumps(state, indent=2))
    return state


def built_rounds(jdir: str) -> list[int]:
    """The rounds that have a manuscript in this journal folder.

    Both places: `submission/`, where builds write now, and the folder root,
    where they wrote before item 17. A project mid-migration has to read
    correctly, and a manuscript left in the root by an older build is still
    evidence about the counter.
    """
    found: list[int] = []
    for d in (os.path.join(jdir, "submission"), jdir):
        if not os.path.isdir(d):
            continue
        found += [int(m.group(1)) for f in os.listdir(d)
                  if (m := MANUSCRIPT_RE.match(f))]
    return found


def current_round(jdir: str) -> int:
    """The round now open here, else 0 if none has begun anywhere.

    The counter is the PROJECT's, not this folder's (item 18). Read off the
    folder, LANGMUIR sat at r7 while a JPCC opened beside it started again at
    r1, and there were then two files called `manuscript_r1.docx` in one
    project meaning different things. `project.yml:revision` already counted
    globally and nothing read it back; it is the source now, and the folder is
    still read as well - a manuscript built before this, or a round_state left
    by a hand that deleted project.yml, is evidence that must not be thrown
    away.
    """
    if not os.path.isdir(jdir):
        return 0
    rounds = built_rounds(jdir)
    opened = round_state(jdir).get("round")
    if isinstance(opened, int) and opened > 0:
        rounds.append(opened)
    rev = project_revision(project_of(jdir))
    if rev > 0:
        rounds.append(rev)
    return max(rounds) if rounds else 0


def round_scope(jdir: str, stems: list[str] | None = None) -> list[str]:
    """The sections this round is limited to, or [] for the whole paper.

    "Just the introduction and methods for now" had nowhere to be recorded, so
    it could only be remembered - and a remembered scope is one that lasts
    until the next session. A section left out is reported as OUT OF THIS
    ROUND'S SCOPE rather than as a gap, which is the same distinction
    `manages` already draws for files (item 23).
    """
    want = round_state(jdir).get("sections")
    if not isinstance(want, list):
        return []
    return [s for s in (stems or SECTION_FILES) if s in want]


def build_round(jdir: str) -> int:
    """The round a build writes to: the open one, and r1 before there is one.

    Every writer of a round-numbered artefact goes through this, so a rebuild
    overwrites `manuscript_r{current}.docx` instead of adding to a pile.
    """
    return max(current_round(jdir), 1)


# One level of nesting, spelled with a single character (item 33).
#
# ACS ends a paper two levels deep - `ASSOCIATED CONTENT` and `AUTHOR
# INFORMATION` are headings, and `Supporting Information`, `Corresponding
# Author`, `Funding Sources` and `Notes` are subheadings under them - while
# `structure.section_order` was a flat list, so the build emitted six sibling
# Heading1s. Two of them are wrong in a way an editor sees: `Funding` outside
# `AUTHOR INFORMATION`, and a top-level `Conflict of Interest`, which is a
# heading no ACS paper carries (their word is `Notes`).
#
#   section_order: [..., ACKNOWLEDGMENT,
#                   AUTHOR INFORMATION, "> Corresponding Author",
#                   "> Funding Sources", "> Notes", REFERENCES]
#
# The marker carries the level and nothing else: the list stays flat, one line
# per section, and every existing `requirements.yml` keeps its meaning because
# a name without the marker is level 1 exactly as before. **A heading with
# children of its own emits no body** - that is what makes `AUTHOR INFORMATION`
# a container rather than a second copy of the corresponding-author block - and
# a name is only read that way when a `>` entry actually follows it, so a flat
# order is untouched.
SUBHEADING_MARK = ">"


def split_level(name: str) -> tuple[int, str]:
    """`"> Notes"` -> (2, "Notes"); anything else -> (1, name)."""
    s = name.strip().strip('"').strip("'").strip()
    if s.startswith(SUBHEADING_MARK):
        return 2, s[len(SUBHEADING_MARK):].strip()
    return 1, s


def strip_levels(order: list[str]) -> list[str]:
    """The same order with the markers off, for readers that want names."""
    return [split_level(n)[1] for n in order]


def section_order(req: dict,
                  stems: list[str] | None = None) -> tuple[list[str], str]:
    """The order to concatenate source_text/*.md in, and why.

    `unknown` is a legitimate value for every field of requirements.yml
    (spec 4.3), and it is the honest one until the guidelines have been read.
    Read as a list it becomes the single section name "unknown", which
    resolves to no file, which silently empties the build - so an unsourced
    order falls back to the scaffold's own and says it did.
    """
    unsourced = ("structure.section_order is still unknown, so the sections "
                 "are concatenated in the scaffold's order; source it from "
                 "the journal's guidelines before submission")
    raw = (req.get("structure.section_order", "") or "").strip()
    if not raw:
        return list(stems or SECTION_FILES), unsourced
    order = [s.strip() for s in raw.strip("[]").split(",") if s.strip()]
    if not order or [s.lower() for s in order] == ["unknown"]:
        return list(stems or SECTION_FILES), unsourced
    return order, ""


# ---------------------------------------------------------------------------
# the journal's section names, and where each one's text actually comes from
# ---------------------------------------------------------------------------

# A journal names its sections in its own vocabulary. Langmuir's guidelines
# list "Experimental Section" and "Results and Discussion"; the scaffold keeps
# methods.md, results.md and discussion.md. Captured faithfully - which is what
# the requirements module is for - that eleven-name order matched no file at
# all. Measured: nine of ten names resolved to nothing, gate 0 fires only at
# zero, and the build came out holding the introduction alone at exit code 0
# while the summary line named all ten sections as if they were in it.
#
# So the order is *resolved* rather than used as a list of file stems. Each
# name becomes one of four things:
#
#   front     - the title block, which pandoc sets from document metadata
#   file      - one or more drafts/source_text/*.md, retitled to the journal's
#               own name for the section
#   statement - end matter, built from plan/authors.md
#   refs      - where the bibliography goes
#
# A name that matches nothing is still read as a file stem, exactly as before,
# and says so rather than vanishing.

def _sec_key(name: str) -> str:
    """A section name reduced to what two spellings of it share."""
    return re.sub(r"[^a-z0-9]+", "_", (name or "").lower()).strip("_")


SECTION_ALIASES: dict[str, tuple[str, str]] = {
    # --- the title block --------------------------------------------------
    "title_abstract": ("front", "title_block"),
    "title": ("front", "title"),
    "title_page": ("front", "title"),
    "article_title": ("front", "title"),
    "running_title": ("front", "running_title"),
    "short_title": ("front", "running_title"),
    "author_list": ("front", "authors"),
    "authors": ("front", "authors"),
    "author_names": ("front", "authors"),
    "authors_and_affiliations": ("front", "authors"),
    "affiliations": ("front", "authors"),
    "byline": ("front", "authors"),
    "abstract": ("front", "abstract"),
    "summary": ("front", "abstract"),
    "synopsis": ("front", "abstract"),
    "keywords": ("front", "keywords"),
    "key_words": ("front", "keywords"),
    # --- the body ---------------------------------------------------------
    "introduction": ("file", "introduction"),
    "background": ("file", "introduction"),
    "introduction_and_background": ("file", "introduction"),
    "methods": ("file", "methods"),
    "method": ("file", "methods"),
    "materials": ("file", "methods"),
    "materials_and_methods": ("file", "methods"),
    "methods_and_materials": ("file", "methods"),
    "methodology": ("file", "methods"),
    "experimental": ("file", "methods"),
    "experimental_section": ("file", "methods"),
    "experimental_methods": ("file", "methods"),
    "experimental_procedures": ("file", "methods"),
    "experimental_details": ("file", "methods"),
    "results": ("file", "results"),
    "discussion": ("file", "discussion"),
    # One journal heading, two files. ACS asks for them combined and the
    # scaffold drafts them apart, which is the right way round: the split is
    # how the outline keeps interpretation out of the results.
    "results_and_discussion": ("file", "results+discussion"),
    "results_and_discussions": ("file", "results+discussion"),
    "conclusion": ("file", "conclusions"),
    "conclusions": ("file", "conclusions"),
    "conclusions_and_outlook": ("file", "conclusions"),
    "summary_and_conclusions": ("file", "conclusions"),
    "figure_captions": ("file", "live_captions"),
    "figure_legends": ("file", "live_captions"),
    "toc_graphic": ("file", "toc_graphic"),
    "toc_abstract_graphic": ("file", "toc_graphic"),
    "table_of_contents_graphic": ("file", "toc_graphic"),
    "graphical_abstract": ("file", "toc_graphic"),
    # --- the end matter ---------------------------------------------------
    "associated_content": ("statement", "supporting_information"),
    "supporting_information": ("statement", "supporting_information"),
    "supporting_information_available": ("statement",
                                         "supporting_information"),
    "supplementary_material": ("statement", "supporting_information"),
    "supplementary_information": ("statement", "supporting_information"),
    "author_information": ("statement", "author_information"),
    "corresponding_author": ("statement", "author_information"),
    "author_contributions": ("statement", "author_contributions"),
    "contributions": ("statement", "author_contributions"),
    "credit_authorship_contribution_statement": ("statement",
                                                 "author_contributions"),
    "funding": ("statement", "funding"),
    "funding_sources": ("statement", "funding"),
    "funding_information": ("statement", "funding"),
    "conflict_of_interest": ("statement", "conflict_of_interest"),
    "conflicts_of_interest": ("statement", "conflict_of_interest"),
    "competing_interests": ("statement", "conflict_of_interest"),
    "declaration_of_competing_interest": ("statement",
                                          "conflict_of_interest"),
    "disclosures": ("statement", "conflict_of_interest"),
    "notes": ("statement", "conflict_of_interest"),
    "data_availability": ("statement", "data_availability"),
    "data_availability_statement": ("statement", "data_availability"),
    "data_sharing_statement": ("statement", "data_availability"),
    "data_and_code_availability": ("statement", "data_availability"),
    "ethics": ("statement", "ethics"),
    "ethics_statement": ("statement", "ethics"),
    "acknowledgment": ("statement", "acknowledgment"),
    "acknowledgments": ("statement", "acknowledgment"),
    "acknowledgement": ("statement", "acknowledgment"),
    "acknowledgements": ("statement", "acknowledgment"),
    # --- AI-use disclosure (spec 17.3) ------------------------------------
    #
    # Journals name this a dozen ways and they are specific about the wording,
    # so every spelling resolves to ONE canonical statement and the heading
    # actually printed is `ai_disclosure.in_paper_heading` verbatim. A
    # paraphrased heading is a copy-editing query at best.
    "declaration_of_generative_ai": ("statement", "ai_disclosure"),
    "declaration_of_generative_ai_and_ai_assisted_technologies":
        ("statement", "ai_disclosure"),
    "declaration_of_generative_ai_and_ai_assisted_technologies_in_the_writing_process":
        ("statement", "ai_disclosure"),
    "declaration_of_ai_use": ("statement", "ai_disclosure"),
    "declaration_of_ai_assisted_technologies": ("statement", "ai_disclosure"),
    "ai_disclosure": ("statement", "ai_disclosure"),
    "use_of_ai": ("statement", "ai_disclosure"),
    "use_of_generative_ai": ("statement", "ai_disclosure"),
    "generative_ai_statement": ("statement", "ai_disclosure"),
    "artificial_intelligence_disclosure": ("statement", "ai_disclosure"),
    "ai_assisted_technologies": ("statement", "ai_disclosure"),

    # --- the bibliography -------------------------------------------------
    "references": ("refs", "references"),
    "reference_list": ("refs", "references"),
    "literature_cited": ("refs", "references"),
    "bibliography": ("refs", "references"),
    "works_cited": ("refs", "references"),
}

# The canonical display name for an alias key, for the two jobs that need
# one: a heading the build has to supply itself (the bibliography, when the
# section order never named it), and a `section_order` entry written in the
# slug form this table also accepts.
#
# Title-casing the key gets almost all of them right - `experimental_section`
# is "Experimental Section", `data_availability_statement` is "Data
# Availability Statement" - so only the keys it gets wrong are listed.
SECTION_DISPLAY: dict[str, str] = {
    "ai_disclosure": "Declaration of Generative AI Use",
    "declaration_of_generative_ai": "Declaration of Generative AI",
    "use_of_ai": "Use of AI",
    "toc_graphic": "TOC Graphic",
    "toc_abstract_graphic": "TOC/Abstract Graphic",
    "table_of_contents_graphic": "Table of Contents Graphic",
    "graphical_abstract": "Graphical Abstract",
    "credit_authorship_contribution_statement":
        "CRediT Authorship Contribution Statement",
    "si": "Supporting Information",
    "title_abstract": "Title and Abstract",
    "key_words": "Keywords",
}

# Lowercase in a title unless they open it. Journals differ on this; these are
# the words every style guide agrees are minor.
_TITLE_MINOR = frozenset({"a", "an", "and", "as", "at", "but", "by", "for",
                          "from", "in", "of", "on", "or", "the", "to", "with"})


def _is_alias_form(name: str) -> bool:
    """Is this the slug spelling of a section name rather than a heading?

    An underscore settles it. So does being entirely lowercase: no journal
    prints `conclusions` over a section, and the two spellings resolve
    identically, so the one that is not a heading can be recognised.
    """
    return "_" in name or (bool(name) and name == name.lower())


def section_display(key: str) -> str:
    """The heading a journal prints for an alias key.

    A review's stems carry a two-digit ORDER PREFIX - `02_defects_and_
    ordering` - because order in a filename beats order in a manifest
    nobody re-reads (review-paper 7). The prefix is bookkeeping and must
    never reach the page: a manuscript with `02 Defects And Ordering`
    printed above a paragraph is the form being mistaken for the answer.
    """
    if key in SECTION_DISPLAY:
        return SECTION_DISPLAY[key]
    key = re.sub(r"^\d{2}_", "", key or "")
    words = [w for w in key.split("_") if w]
    return " ".join(w if i and w in _TITLE_MINOR else w.capitalize()
                    for i, w in enumerate(words)) or key


# The files the scaffold guarantees. A journal order that names one of
# these and finds no file on disk is a hole in the built document rather than
# a naming mismatch, and gate 0 refuses on it - a .docx with no Methods in it
# is exactly the "looks like a manuscript and is not one" failure the other
# gates exist to stop.
#
# A FUNCTION rather than a constant, because for a review the guaranteed set
# is whatever its outline names (review-paper 7). The constant stays for the
# research default and for every caller that has no project in hand.
CORE_STEMS = frozenset(SECTION_FILES)


def core_stems(project: str) -> frozenset:
    return frozenset(section_files(project))

# Sections that carry no prose of their own. Naming one and finding no file is
# normal: the captions and the graphic are written by other modules and may
# legitimately not exist yet.
OPTIONAL_STEMS = frozenset({"live_captions", "toc_graphic"})


def resolve_order(order: list[str],
                  project: str) -> tuple[list[dict], list[str]]:
    """The journal's section names, each tied to what will fill it.

    One entry per name - kind, target, the source files that exist and the
    ones that do not - plus warnings about names this module does not know.
    Order is preserved; a name resolving to something already placed is
    dropped rather than duplicated.
    """
    st = source_text_dir(project)
    out: list[dict] = []
    warnings: list[str] = []
    placed: set[tuple[str, str]] = set()
    used_stems: set[str] = set()

    # Levels first, because whether an entry is a container depends on what
    # comes AFTER it: a name is a group heading when a `>` entry follows it,
    # and an ordinary section otherwise. Deciding that per entry as we go
    # would need a look-ahead in the middle of the resolution loop.
    levels = [split_level(n) for n in order]
    names = [n for _lv, n in levels]
    has_children = [False] * len(levels)
    for i, (lv, _n) in enumerate(levels):
        if lv == 1:
            has_children[i] = i + 1 < len(levels) and levels[i + 1][0] == 2
        elif not any(levels[j][0] == 1 for j in range(i)):
            # A `>` before any level-1 name has nothing to sit under. Read as
            # a top-level section, and said out loud rather than nested into
            # a parent that does not exist.
            warnings.append(
                "structure.section_order marks %r as a subheading and there "
                "is no section above it for it to sit under, so it is built "
                "as a top-level heading. Put the heading it belongs to "
                "before it." % order[i])
            levels[i] = (1, names[i])

    for i, name in enumerate(names):
        level, _ = levels[i]
        key = _sec_key(name)
        known = key in SECTION_ALIASES
        kind, target = SECTION_ALIASES.get(key, ("file", key))

        # A heading with subheadings under it is a container and emits no body
        # of its own. `ASSOCIATED CONTENT` resolves to the supporting-
        # information statement when a journal names it alone, which is right
        # and stays right; with `> Supporting Information` under it, the
        # statement belongs to the child and the parent is a heading. It is
        # deliberately not added to `placed`, so the child still resolves.
        if has_children[i]:
            out.append({"name": name, "kind": "group", "target": "",
                        "stems": [], "files": [], "missing": [],
                        "display_supplied": "", "retitle": False,
                        "level": level})
            continue

        if not known:
            warnings.append(
                "structure.section_order names %r, which is not a section "
                "name this module knows. It is being read as "
                "the section file %s.md; add it to SECTION_ALIASES if this "
                "journal calls one of the standard sections that."
                % (name, key))
        if (kind, target) in placed:
            continue
        placed.add((kind, target))
        stems = target.split("+") if kind == "file" else []
        stems = [s for s in stems if s not in used_stems]
        used_stems.update(stems)
        entry = {"name": name, "kind": kind, "target": target,
                 "stems": stems, "files": [], "missing": [],
                 "display_supplied": "", "level": level}
        for stem in stems:
            path = os.path.join(st, stem + ".md")
            if os.path.isfile(path):
                entry["files"].append(stem)
            else:
                entry["missing"].append(stem)
        # An order written in file stems is the scaffold's own, and its names
        # are not headings. Only a journal's own vocabulary retitles a section.
        entry["retitle"] = kind == "file" and key not in stems
        # `_sec_key()` normalizes a name for RESOLUTION, and the name was then
        # printed verbatim: `experimental_section` in a section_order resolved
        # perfectly to methods.md and put a literal `experimental_section`
        # heading in the .docx. The engine understood an alias form it defines
        # itself and produced an unpublishable heading without a word of
        # complaint, which is what makes it an engine problem rather than
        # author error. Only the entries whose name reaches the page are
        # checked - the scaffold's own order is all slugs, and none of them is
        # a heading.
        if known and _is_alias_form(name) and (
                entry["retitle"] or kind in ("statement", "refs")):
            display = section_display(key)
            if display != name:
                warnings.append(
                    "structure.section_order names %r, which is the alias "
                    "spelling and not a heading; %r is what a build would "
                    "have put on the page. The heading is %r instead - write "
                    "the journal's own display name in section_order to set "
                    "it exactly." % (name, name, display))
                entry["name"] = display
                entry["display_supplied"] = name
        out.append(entry)
    return out, warnings


def _split_heading(body: str) -> tuple[str, str]:
    """A markdown file's own level-1 heading, and everything after it."""
    lines = (body or "").split("\n")
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        m = re.match(r"^#\s+(.*?)\s*#*$", line)
        if m:
            return m.group(1).strip(), "\n".join(lines[i + 1:]).strip()
        break
    return "", (body or "").strip()


# Item 140. The drafter wrote `## Introduction` and `## Experimental Section`
# over `### Materials`, one level deeper than the scaffold's convention, and
# `_split_heading` takes a LEVEL-1 heading only - so the drafted heading went
# through as body text under the journal's retitled one, the methods heading
# appeared twice, and every subsection sat a level too deep. format-check
# caught the introduction's level and nothing else.
_ATX_RE = re.compile(r"^(#{1,6})[ \t]+(.*?)[ \t]*#*[ \t]*$")


def _section_names(name: str, stem: str) -> set[str]:
    """The keys a file's own opening heading may carry and still be the
    section heading: the journal's name, the stem, and the stem's display
    name. Not every alias - `## Materials` opening methods.md is the first
    subsection, and `materials` is an alias of methods."""
    return {k for k in (_sec_key(name), _sec_key(stem),
                        _sec_key(section_display(stem))) if k}


def normalize_section_headings(raw: str, names: set[str],
                               level: int = 1) -> tuple[str, str, str]:
    """(the file's section heading, the body under it, what was fixed).

    The opening heading is the SECTION heading when it is level 1 (as
    before), or when it carries the section's own name and every heading
    after it is deeper - `## Experimental Section` over `### Materials`. The
    subsections under it are then lifted so the shallowest sits one level
    below the section. Only ever lifted, never pushed down: a file whose
    subheadings already sit at the section's own level is left as it was.
    """
    lines = (raw or "").split("\n")
    heads = [(i, len(m.group(1)), m.group(2).strip())
             for i, ln in enumerate(lines) if (m := _ATX_RE.match(ln))]
    first = next((i for i, ln in enumerate(lines) if ln.strip()), None)
    head, notes = "", []
    if heads and first == heads[0][0]:
        i0, lv0, text0 = heads[0]
        deeper = all(lv > lv0 for _i, lv, _t in heads[1:])
        if lv0 == 1 or (_sec_key(text0) in names and deeper):
            head = text0
            del lines[i0]
            heads = [(i - 1, lv, t) for i, lv, t in heads[1:]]
            if lv0 != 1:
                notes.append("its section heading `%s %s` was written at "
                             "level %d; it is the section heading, so it is "
                             "used once, at the journal's level"
                             % ("#" * lv0, text0, lv0))
    if heads:
        shallow = min(lv for _i, lv, _t in heads)
        lift = shallow - (level + 1)
        if lift > 0:
            for i, lv, t in heads:
                lines[i] = "#" * (lv - lift) + " " + t
            notes.append("its subheadings started at level %d under a "
                         "level-%d section; lifted %d level%s"
                         % (shallow, level, lift, "" if lift == 1 else "s"))
    return head, "\n".join(lines).strip(), "; ".join(notes)


SKELETON_ORDER = "[title_abstract, introduction, methods, results, discussion]"


def order_is_sourced(req: dict) -> bool:
    """Is structure.section_order the journal's, rather than the scaffold's
    own five stems or `unknown`?"""
    raw = " ".join((req.get("structure.section_order") or "").split())
    return bool(raw) and raw.lower() not in ("unknown", "null", "none",
                                             SKELETON_ORDER)


def _md_block(text: str, heading: str) -> str:
    """The body written under an ATX heading, without the heading itself."""
    if not heading:
        return ""
    want = _sec_key(heading)
    out: list[str] = []
    level = None
    for line in (text or "").splitlines():
        m = re.match(r"^(#{1,6})\s+(.*?)\s*#*$", line)
        if m:
            if level is None:
                got = _sec_key(m.group(2))
                if got == want or got.startswith(want) or want.startswith(got):
                    level = len(m.group(1))
                continue
            if len(m.group(1)) <= level:
                break
            out.append(line)
            continue
        if level is not None:
            out.append(line)
    return re.sub(r"<!--.*?-->", "", "\n".join(out), flags=re.DOTALL).strip()


def _has_content(md: str) -> bool:
    """Is there anything here, or is it the template's empty form?

    An empty markdown table is not content. `| | |` under a rule is what
    authors.md ships with, and a statement built from it would put an empty
    two-column table where the journal asked for a sentence.
    """
    body = re.sub(r"<!--.*?-->", "", md or "", flags=re.DOTALL)
    lines = [ln for ln in body.splitlines() if ln.strip()]
    if not lines:
        return False
    if any(ln.strip() for ln in lines if not ln.strip().startswith("|")):
        return True
    seen_rule = False
    for ln in lines:
        cells = [c.strip() for c in ln.strip().strip("|").split("|")]
        if all(re.fullmatch(r"[-: ]*", c) for c in cells):
            seen_rule = True
            continue
        if seen_rule and any(cells):
            return True
    return False


# ---------------------------------------------------------------------------
# the title block - the front matter pandoc sets from metadata
# ---------------------------------------------------------------------------

# title_abstract.md is a form: `# Title` is the label on the box, not the
# paper's title. pandoc passed the label straight through, so every build
# carried a level-1 heading reading the literal word "Title", the real title
# as body text under it, and Abstract and Keywords a level below the sections
# they sit beside. format-check asked for a Title-styled paragraph and nothing
# ever emitted one, so that warning was unsatisfiable on every build.
#
# Reading the form and handing pandoc metadata is what makes it use the Title,
# Author, AbstractTitle and Abstract styles the reference document already
# sets. An author who deletes the label and writes `# Colloidal Stability
# of ...` instead gets the same result: a level-1 heading that is not one of
# the form's labels IS the title.

TITLE_LABELS = {"title", "running_title", "short_title", "abstract",
                "keywords", "key_words"}


def parse_title_abstract(text: str) -> dict:
    """title / running_title / abstract / keywords out of the form, plus
    anything written under a heading the form does not know about."""
    text = re.sub(r"<!--.*?-->", "", text or "", flags=re.DOTALL)
    blocks: list[dict] = []
    cur: dict | None = None
    for line in text.splitlines():
        m = re.match(r"^(#{1,6})\s+(.*?)\s*#*$", line)
        if m:
            cur = {"level": len(m.group(1)), "head": m.group(2).strip(),
                   "body": []}
            blocks.append(cur)
        elif cur is not None:
            cur["body"].append(line)
    out = {"title": "", "running_title": "", "abstract": "", "keywords": "",
           "extra": ""}
    extra: list[str] = []
    for b in blocks:
        key = _sec_key(b["head"])
        body = "\n".join(b["body"]).strip()
        if key not in TITLE_LABELS:
            if b["level"] == 1 and not out["title"]:
                out["title"] = b["head"]
                if body:
                    extra.append(body)
            else:
                extra.append("#" * b["level"] + " " + b["head"]
                             + ("\n\n" + body if body else ""))
            continue
        if key == "title":
            if not out["title"]:
                out["title"] = " ".join(body.split("\n")[0].split())
        elif key in ("running_title", "short_title"):
            out["running_title"] = " ".join(body.split("\n")[0].split())
        elif key == "abstract":
            out["abstract"] = body
        else:
            out["keywords"] = " ".join(body.split("\n")[0].split())
    out["extra"] = "\n\n".join(x for x in extra if x.strip()).strip()
    return out


# ---------------------------------------------------------------------------
# plan/authors.md and plan/affiliations.md
# ---------------------------------------------------------------------------
# Who wrote it, where they are, what each of them did, and who paid for it.
#
# Read by column heading rather than by column position. authors.md holds two
# tables - the author list and the CRediT contribution matrix - and the rule
# that used to tell them apart, "five cells or more is an author row", reads
# every row of a fifteen-column matrix as an author whose name is the letter
# x. The heading row says which column is which, so the matrix is never
# mistaken for the list, and a project that adds an `initials` column or drops
# ORCID keeps building.

def _tables(text: str) -> list[dict]:
    """Every pipe table in a markdown file: its header labels and its rows.

    The row of dashes marks the line above it as the header. Anything that is
    not a table row ends the table, so two tables separated by a paragraph are
    two tables and not one long one.
    """
    text = re.sub(r"<!--.*?-->", "", text or "", flags=re.DOTALL)
    tables: list[dict] = []
    cur: dict | None = None
    for line in text.splitlines():
        s = line.strip()
        if not s.startswith("|"):
            cur = None
            continue
        cells = [c.strip() for c in s.strip("|").split("|")]
        if cells and all(re.fullmatch(r"[-: ]*", c) for c in cells):
            if cur is not None and cur["rows"] and not cur["header"]:
                cur["header"] = cur["rows"].pop()
            continue
        if cur is None:
            cur = {"header": [], "rows": []}
            tables.append(cur)
        cur["rows"].append(cells)
    return [t for t in tables if t["header"] or t["rows"]]


# Column heading -> the field it holds. Spellings that turned up in real
# projects are all here rather than being normalised away at the call site.
AUTHOR_FIELDS = {
    "order": "order", "no": "order", "num": "order", "number": "order",
    "position": "order",
    "name": "name", "author": "name", "author_name": "name",
    "full_name": "name",
    "initials": "initials", "initial": "initials",
    "affiliation": "aff", "affiliations": "aff", "affiliation_s": "aff",
    "affil": "aff", "address": "aff", "institution": "aff",
    "orcid": "orcid", "orcid_id": "orcid",
    "email": "email", "e_mail": "email", "email_address": "email",
}

# The positional shape the first template shipped, for a file whose header row
# has since been edited into something this parser does not recognise.
LEGACY_AUTHOR_COLS = {"order": 0, "name": 1, "aff": 2, "orcid": 3, "email": 4}


def _author_columns(header: list[str]) -> dict[str, int]:
    cols: dict[str, int] = {}
    for i, h in enumerate(header):
        key = _sec_key(h)
        field = AUTHOR_FIELDS.get(key)
        if field is None and i == 0 and key == "":
            field = "order"          # the `#` column: _sec_key eats the hash
        if field and field not in cols:
            cols[field] = i
    return cols


def _author_row(cells: list[str], cols: dict[str, int]) -> dict | None:
    def cell(field: str) -> str:
        i = cols.get(field)
        return cells[i].strip() if i is not None and i < len(cells) else ""

    name = cell("name")
    if not name or _sec_key(name) in ("name", "author"):
        return None
    return {"order": cell("order"), "name": name, "initials": cell("initials"),
            "affiliation": cell("aff"), "orcid": cell("orcid"),
            "email": cell("email")}


def parse_authors(text: str) -> dict:
    """The author list and the corresponding author out of authors.md.

    The table with a `name` column is the author list. The contribution matrix
    below it is read by `parse_contributions` and ignored here.
    """
    corresponding = ""
    for line in re.sub(r"<!--.*?-->", "", text or "",
                       flags=re.DOTALL).splitlines():
        s = line.strip()
        if s.lower().startswith("corresponding author"):
            corresponding = s.split(":", 1)[1].strip() if ":" in s else ""
            break

    found: tuple[dict, dict[str, int]] | None = None
    for t in _tables(text):
        cols = _author_columns(t["header"])
        if "name" in cols and {"orcid", "email", "aff"} & set(cols):
            found = (t, cols)
            break
    if found is None:
        for t in _tables(text):
            if any(len(c) >= 5 for c in t["rows"]):
                found = (t, LEGACY_AUTHOR_COLS)
                break
    rows: list[dict] = []
    if found:
        for cells in found[0]["rows"]:
            row = _author_row(cells, found[1])
            if row:
                rows.append(row)

    # The `#` column is submission order, and the byline follows it - so a
    # table sorted by hand into the wrong order still produces the right
    # byline, and a first author cannot become third by a stray cut and paste.
    # Only when every row has a number: a half-numbered table is somebody
    # mid-edit, and inventing an order for it is worse than keeping theirs.
    nums = [r["order"] for r in rows]
    if nums and all(re.fullmatch(r"\d+", n or "") for n in nums):
        rows.sort(key=lambda r: int(r["order"]))
    return {"authors": rows, "corresponding": corresponding}


def parse_affiliations(text: str) -> dict:
    """key -> institution, from the table in affiliations.md.

    Keyed rather than written out per author so one address is typed once: the
    byline numbers them from author order at build time, which is what makes
    `A,B` on one author work at all.
    """
    out: dict[str, str] = {}
    for t in _tables(text):
        head = [_sec_key(h) for h in t["header"]]
        if not head or head[0] not in ("key", "id", "code", "letter", "ref"):
            continue
        if not any(h.startswith("affiliation")
                   or h in ("institution", "address") for h in head[1:]):
            continue
        for cells in t["rows"]:
            if len(cells) < 2:
                continue
            k, v = cells[0].strip(), cells[1].strip()
            if k and v and _sec_key(k) not in ("key", "id", "code"):
                out[k.upper()] = v
        break
    return out


def _aff_texts(row: dict, affs: dict) -> list[str]:
    """The institutions one author belongs to, in the order they wrote them.

    The cell holds keys into the affiliations table - `A`, or `A,B` for two.
    A cell that is not keys is taken as the institution itself, which is what
    projects written before affiliations.md existed have in it.
    """
    cell = (row.get("affiliation") or "").strip()
    if not cell:
        return []
    parts = [p.strip().upper() for p in re.split(r"[,;/]", cell) if p.strip()]
    if affs and parts and all(p in affs for p in parts):
        return [affs[p] for p in parts]
    return [cell]


def _name_key(s: str) -> str:
    """A name reduced to what a name and its own initials share."""
    return re.sub(r"[^a-z]", "", (s or "").lower())


def match_author(label: str, authors: list[dict]) -> dict | None:
    """The author a contribution row or a grant recipient names.

    Matches the full name, the initials column, or initials derived from the
    name - `A.B.` in the funding table is Ada Bell in the author list, and a
    matrix that names people by initials is the normal way to fill one in.
    """
    key = _name_key(label)
    if not key:
        return None
    for a in authors:
        if _name_key(a["name"]) == key:
            return a
    for a in authors:
        if a.get("initials") and _name_key(a["initials"]) == key:
            return a
    for a in authors:
        if _name_key(_initials_of(a["name"])) == key:
            return a
    return None


# ---------------------------------------------------------------------------
# The contribution matrix
# ---------------------------------------------------------------------------
# One row per author, one column per thing a person can do on a paper, an `x`
# in every cell that applies. The column heading is the plain-English word;
# the statement prints CRediT's own wording, because that is what the journal
# asks for and nobody should have to type it twice.

CREDIT_ROLES = [
    ("conceptualization", "Conceptualization"),
    ("methodology", "Methodology"),
    ("software", "Software"),
    ("validation", "Validation"),
    ("formal_analysis", "Formal analysis"),
    ("investigation", "Investigation"),
    ("resources", "Resources"),
    ("data_curation", "Data curation"),
    ("writing_original_draft", "Writing - original draft"),
    ("writing_review_editing", "Writing - review & editing"),
    ("visualization", "Visualization"),
    ("supervision", "Supervision"),
    ("project_administration", "Project administration"),
    ("funding_acquisition", "Funding acquisition"),
]
CREDIT_PRINTED = dict(CREDIT_ROLES)

CREDIT_ALIASES = {
    "concept": "conceptualization", "conceptualization": "conceptualization",
    "conceptualisation": "conceptualization", "idea": "conceptualization",
    "methods": "methodology", "method": "methodology",
    "methodology": "methodology", "protocol": "methodology",
    "software": "software", "code": "software", "scripts": "software",
    "validation": "validation", "verification": "validation",
    "replication": "validation",
    "analysis": "formal_analysis", "formal_analysis": "formal_analysis",
    "stats": "formal_analysis", "statistics": "formal_analysis",
    "experiments": "investigation", "investigation": "investigation",
    "experimental_work": "investigation", "data_collection": "investigation",
    "measurements": "investigation", "synthesis": "investigation",
    "resources": "resources", "materials": "resources",
    "reagents": "resources", "instruments": "resources",
    "data": "data_curation", "data_curation": "data_curation",
    "data_management": "data_curation",
    "draft": "writing_original_draft", "writing": "writing_original_draft",
    "original_draft": "writing_original_draft",
    "writing_original_draft": "writing_original_draft",
    "revision": "writing_review_editing", "review": "writing_review_editing",
    "editing": "writing_review_editing",
    "review_editing": "writing_review_editing",
    "writing_review_editing": "writing_review_editing",
    "figures": "visualization", "visualization": "visualization",
    "visualisation": "visualization", "plots": "visualization",
    "supervision": "supervision", "mentoring": "supervision",
    "admin": "project_administration",
    "administration": "project_administration",
    "project_admin": "project_administration",
    "project_administration": "project_administration",
    "funding": "funding_acquisition",
    "funding_acquisition": "funding_acquisition", "grants": "funding_acquisition",
}

# What counts as a tick. Deliberately narrow: a cell holding a note rather
# than a mark is not a claim of authorship credit, and reading one as a tick
# would put a role in the submitted statement that nobody put there.
MARK_RE = re.compile(r"^(x+|y|yes|✓|✔|●|•|\*|1)$", re.IGNORECASE)


def _is_mark(cell: str) -> bool:
    s = (cell or "").strip()
    if not s or s in ("-", "–", "—", "✗", "✘", "n", "no", "0"):
        return False
    return bool(MARK_RE.fullmatch(s))


def _role_key(label: str) -> str:
    return CREDIT_ALIASES.get(_sec_key(label), "")


def parse_contributions(text: str) -> dict:
    """Who did what, out of the contribution matrix.

    Falls back to the two-column `| author | roles |` list the first template
    shipped, so a project that was scaffolded before the matrix existed still
    produces a statement. The header row tells them apart.
    """
    matrix: dict | None = None
    legacy: dict | None = None
    for t in _tables(text):
        head = t["header"]
        if not head or _sec_key(head[0]) not in ("author", "name", ""):
            continue
        rest = head[1:]
        if len(rest) == 1 and _sec_key(rest[0]) in ("roles", "role",
                                                    "contribution",
                                                    "contributions"):
            legacy = legacy or t
            continue
        if sum(1 for h in rest if _role_key(h)) >= 2:
            matrix = matrix or t

    if matrix is not None:
        cols = [{"label": h, "role": _role_key(h),
                 "printed": CREDIT_PRINTED.get(_role_key(h), h.strip())}
                for h in matrix["header"][1:]]
        rows: list[dict] = []
        for cells in matrix["rows"]:
            if not cells or not cells[0].strip():
                continue
            name = cells[0].strip()
            if _sec_key(name) in ("author", "name"):
                continue
            marked = [c for i, c in enumerate(cols)
                      if i + 1 < len(cells) and _is_mark(cells[i + 1])]
            rows.append({"author": name,
                         "roles": [c["printed"] for c in marked],
                         "keys": [c["role"] for c in marked if c["role"]]})
        return {"form": "matrix", "rows": rows, "columns": cols,
                "custom_columns": [c["label"] for c in cols if not c["role"]]}

    if legacy is not None:
        rows = []
        for cells in legacy["rows"]:
            if len(cells) < 2 or not cells[0].strip():
                continue
            name = cells[0].strip()
            if _sec_key(name) in ("author", "name"):
                continue
            labels = [p.strip() for p in re.split(r"[,;]", cells[1])
                      if p.strip()]
            rows.append({
                "author": name,
                "roles": [CREDIT_PRINTED.get(_role_key(p), p) for p in labels],
                "keys": [_role_key(p) for p in labels if _role_key(p)]})
        if rows:
            return {"form": "list", "rows": rows, "columns": [],
                    "custom_columns": []}
    return {"form": "none", "rows": [], "columns": [], "custom_columns": []}


def contributions_statement(info: dict) -> str:
    """The CRediT statement, in author-list order.

    Author order is the `#` column, not the matrix's row order: the matrix is
    filled in by whoever is at the keyboard and gets rows appended to the
    bottom, and a statement that followed it would print the byline in the
    order people happened to be added.
    """
    rows = (info.get("contributions") or {}).get("rows") or []
    authors = info.get("authors") or []
    if not rows:
        return ""
    rank = {id(a): i for i, a in enumerate(authors)}

    def sort_key(item: tuple[int, dict]) -> tuple[int, int]:
        i, r = item
        a = match_author(r["author"], authors)
        return (rank.get(id(a), len(authors)) if a else len(authors), i)

    parts: list[str] = []
    for _, r in sorted(enumerate(rows), key=sort_key):
        if not r["roles"]:
            continue
        a = match_author(r["author"], authors)
        parts.append("**%s:** %s." % (a["name"] if a else r["author"],
                                      ", ".join(r["roles"])))
    return " ".join(parts)


# ---------------------------------------------------------------------------
# Funding
# ---------------------------------------------------------------------------

FUNDER_COLS = ("funder", "sponsor", "agency", "source", "funding_source")
AWARD_COLS = ("award", "award_number", "award_no", "grant", "grant_number",
              "number", "grant_award_number", "id")
RECIPIENT_COLS = ("to", "recipient", "held_by", "pi", "author", "awardee")


def parse_funding(text: str) -> dict:
    """The grant table under `## Funding`, and any prose written beside it."""
    block = _md_block(text, "Funding")
    grants: list[dict] = []
    for t in _tables(block):
        head = [_sec_key(h) for h in t["header"]]
        if not head or head[0] not in FUNDER_COLS:
            continue
        cols = {"funder": 0}
        for i, h in enumerate(head):
            if h in AWARD_COLS and "award" not in cols:
                cols["award"] = i
            elif h in RECIPIENT_COLS and "to" not in cols:
                cols["to"] = i
        for cells in t["rows"]:
            def cell(field: str) -> str:
                i = cols.get(field)
                return cells[i].strip() if i is not None and i < len(cells) else ""
            if not cell("funder") or _sec_key(cell("funder")) in FUNDER_COLS:
                continue
            grants.append({"funder": cell("funder"), "award": cell("award"),
                           "to": cell("to")})
        break
    prose = "\n".join(ln for ln in block.splitlines()
                      if not ln.strip().startswith("|")).strip()
    return {"grants": grants, "prose": prose if _has_content(prose) else ""}


def funding_statement(info: dict) -> str:
    """The Funding statement.

    Prose wins over the table: a funder that requires exact wording gets it,
    and the table stays as the record of what the wording is about.
    """
    f = info.get("funding") or {}
    if f.get("prose"):
        return f["prose"]
    grants = f.get("grants") or []
    if not grants:
        return ""
    bits: list[str] = []
    for g in grants:
        detail = ", ".join(x for x in (g.get("award", ""),
                                       ("to " + g["to"]) if g.get("to") else "")
                           if x)
        bits.append(g["funder"] + (" (%s)" % detail if detail else ""))
    joined = (bits[0] if len(bits) == 1
              else ", ".join(bits[:-1]) + " and " + bits[-1])
    return "This work was supported by %s." % joined


def source_text(project: str, name: str) -> str:
    return _read(os.path.join(source_text_dir(project), name))


# ---------------------------------------------------------------------------
# Front matter lives in plan/, and used to live in the round folder
# (spec analysis-and-front-matter 3)
# ---------------------------------------------------------------------------
#
# `drafts/source_text/` is renamed forward on every round, so front matter held
# there was copied into r1..r8 as eight files meant to be identical - and an
# author list belongs to the project, not to a round. It moved to plan/ for the
# reason drafts/rough_draft.md never went into source_text/ at all.
#
# THE FALLBACK IS READ-ONLY AND STAYS THAT WAY. Nothing here moves a user's
# file for them. Projects scaffolded before the move keep working, and the path
# that was READ is the path REPORTED - a diagnostic that names plan/authors.md
# to somebody whose author list is in source_text_r3/ sends them to an empty
# file, and a wrong path in a diagnostic is worse than none (`dpfx`, above).
#
# Two fallbacks deep for affiliations rather than one, because that file has
# been renamed twice: it was split out of authors.md as
# affiliations_and_funding.md, and shortened to affiliations.md when it moved.

FRONT_MATTER_NAMES = {
    "authors": ["authors.md"],
    "affiliations": ["affiliations.md", "affiliations_and_funding.md"],
}


# The two front-matter files live in a folder of their own since 2026-09-24:
# `plan/author_information/`, with `conflict_statements/` beside them.
#
# The folder is what the COI forms needed. A signed disclosure is one file per
# author, returned over weeks, in whatever format the journal's system emits -
# a pile that has to live somewhere and that nothing should try to parse. Put
# loose in `plan/` it is indistinguishable from the project's own planning
# files; under `author_information/` it sits next to the author list it is
# checked against, and one folder holds everything about the people on the
# paper.
#
# `plan/authors.md` and `plan/affiliations.md` are still read where they are,
# and are moved for nobody - the read-only rule below, unchanged.
AUTHOR_INFO_FOLDER = "author_information"
CONFLICT_FOLDER = "conflict_statements"
CONFLICT_BLANK_FOLDER = "blank_form"


def plan_dir(project: str) -> str:
    """`plan/` when the project has one, the project root when it does not."""
    plan = os.path.join(project, "plan")
    return plan if os.path.isdir(plan) else project


def author_info_dir(project: str) -> str:
    return os.path.join(plan_dir(project), AUTHOR_INFO_FOLDER)


def blank_coi_dir(project: str) -> str:
    """Where the journal's own BLANK form waits to be signed.

    A subfolder, not a reserved filename. `conflict_statements()` counts
    files and a blank form sitting among them reads as a returned one - an
    author marked as having signed because somebody downloaded the form.
    A directory is skipped by that reader for free, and it is also the honest
    shape: a journal can want two forms, or a form and an instructions page.
    """
    return os.path.join(conflict_dir(project), CONFLICT_BLANK_FOLDER)


def conflict_dir(project: str) -> str:
    """Where the signed competing-interest forms wait.

    Always the new location, even in a project whose author list is still at
    `plan/authors.md`: there is no older place for these to have been, so
    there is nothing to be backward compatible with and no reason to scatter
    them by which layout a project's front matter happens to be in.
    """
    return os.path.join(author_info_dir(project), CONFLICT_FOLDER)


def front_matter_candidates(project: str, which: str) -> list[str]:
    """Every path this project might hold `which` at, best first."""
    names = FRONT_MATTER_NAMES[which]
    plan = plan_dir(project)
    info = os.path.join(plan, AUTHOR_INFO_FOLDER)
    st = source_text_dir(project)
    return ([os.path.join(info, n) for n in names]
            + [os.path.join(plan, n) for n in names]
            + [os.path.join(st, n) for n in names])


def _front_matter_has_data(which: str, text: str) -> bool:
    """Is there anything FILLED IN here, as opposed to a scaffolded stub?

    The stub is not empty - it carries prose, headings and an empty table row -
    so an emptiness test on the file is useless. What is tested is whether the
    parsers this file exists to feed get anything out of it.
    """
    if which == "authors":
        info = parse_authors(text)
        return bool(info["authors"] or info["corresponding"]
                    or re.search(r"^##\s+[A-Z]{1,4}\s*[-\u2014\u2013]\s*\S",
                                 text or "", re.M))
    funding = parse_funding(text)
    return bool(parse_affiliations(text) or funding["grants"]
                or funding["prose"])


def front_matter_path(project: str, which: str) -> str:
    """Where this project's author list or affiliations actually are.

    The first candidate that is FILLED IN, then the first that merely exists,
    then the canonical plan/ path - so a message about a missing file names the
    place to create it rather than the place it used to be.

    WHY "FILLED IN" AND NOT "EXISTS". Front matter moved to plan/, so
    scaffold.py writes a blank plan/authors.md into every project - INCLUDING
    an old project re-run through setup-project-directory to repair it, which
    is a thing that skill explicitly invites. A rule of "plan/ wins because it
    exists" would put that blank stub in front of an author list somebody
    filled in three rounds ago, and the paper would build with an empty byline
    and no error anywhere. Measured on 2026-09-08: the manuscript suite's
    ingest fixture went from three authors to none the moment the move landed,
    which is what this rule is here to stop.
    """
    cands = front_matter_candidates(project, which)
    present = [c for c in cands if os.path.isfile(c)]
    if not present:
        return cands[0]
    filled = [c for c in present if _front_matter_has_data(which, _read(c))]
    return (filled or present)[0]


def front_matter_texts(project: str, which: str) -> list[str]:
    """Every existing copy, best first.

    End matter is read across all of them, not just the chosen one: a project
    part-way through the move can have its author table in plan/ and its Ethics
    statement still in the round folder, and losing a statement to a file
    ranking is the same silent hole the rule above closes for the byline.
    """
    return [_read(c) for c in front_matter_candidates(project, which)
            if os.path.isfile(c)]


def front_matter_text(project: str, which: str) -> str:
    return _read(front_matter_path(project, which))


def fm_rel(project: str, which: str) -> str:
    """The resolved path as it should appear in a message, project-relative."""
    return os.path.relpath(front_matter_path(project, which),
                           project).replace(os.sep, "/")


def author_record(project: str) -> dict:
    """Everything the two author files hold, read once.

    Both files are read wherever they are (`front_matter_path`), and authors.md
    is still the fallback for affiliations and funding - a project written
    before the 2026 split keeps everything it had in one file and still builds.
    """
    authors_md = front_matter_text(project, "authors")
    aff_md = front_matter_text(project, "affiliations")
    info = parse_authors(authors_md)
    info["affiliations"] = (parse_affiliations(aff_md)
                            or parse_affiliations(authors_md))
    info["contributions"] = parse_contributions(authors_md)
    funding = parse_funding(aff_md)
    if not funding["grants"] and not funding["prose"]:
        funding = parse_funding(authors_md)
    info["funding"] = funding
    return info


def author_block(info: dict) -> list[str]:
    """The author line, the numbered affiliations and the corresponding
    address, as the paragraphs pandoc sets in the Author style.

    One line of names rather than one paragraph per author: that is what an
    accepted manuscript looks like, and pandoc gives every metadata author of
    its own a centred paragraph.
    """
    rows = info.get("authors") or []
    if not rows:
        return []
    known = info.get("affiliations") or {}
    affs: dict[str, int] = {}
    for r in rows:
        for a in _aff_texts(r, known):
            if a not in affs:
                affs[a] = len(affs) + 1
    corr = (info.get("corresponding") or "").lower()

    def is_corr(r: dict) -> bool:
        if corr:
            return (r["name"].lower() in corr
                    or bool(r["email"]) and r["email"].lower() in corr)
        return len(rows) == 1 and bool(r["email"])

    names: list[str] = []
    star = False
    for r in rows:
        marks = [str(affs[a]) for a in _aff_texts(r, known)]
        if is_corr(r):
            marks.append("\\*")
            star = True
        names.append(r["name"] + ("^" + ",".join(marks) + "^" if marks else ""))
    lines = [", ".join(names)]
    for a, n in sorted(affs.items(), key=lambda kv: kv[1]):
        lines.append("^%d^%s" % (n, a))
    who = [r for r in rows if is_corr(r)]
    if who and star:
        lines.append("\\*Corresponding author. "
                     + (who[0]["email"] or info.get("corresponding", "")))
    elif info.get("corresponding"):
        lines.append("Corresponding author: " + info["corresponding"])
    return [ln for ln in lines if ln.strip()]


# ---------------------------------------------------------------------------
# The author files, checked
# ---------------------------------------------------------------------------
# Authorship is the one thing in a submission that cannot be repaired after the
# fact: a missing figure is an email, a missing coauthor is a correction
# notice. So the two files get their own read, and it reports rather than
# edits - who is credited with what is the user's call and never this engine's.

ORCID_RE = re.compile(r"^(?:https?://orcid\.org/)?"
                      r"\d{4}-\d{4}-\d{4}-\d{3}[\dX]$", re.IGNORECASE)


def authors_report(project: str) -> dict:
    """Everything the author files say, and everything wrong with them."""
    info = author_record(project)
    rows = info["authors"]
    affs = info["affiliations"]
    contrib = info["contributions"]
    found: list[dict] = []

    def add(severity: str, detail: str, where: str = "authors.md") -> None:
        found.append({"severity": severity, "detail": detail, "where": where})

    if not rows:
        add("gap", "the author list is empty - the build has no byline")

    seen: dict[str, str] = {}
    for r in rows:
        key = _name_key(r["name"])
        if key in seen:
            add("blocking", f"{r['name']} is in the author list twice")
        seen[key] = r["name"]
        cell = (r["affiliation"] or "").strip()
        parts = [p.strip().upper() for p in re.split(r"[,;/]", cell)
                 if p.strip()]
        # A short cell is a key into the affiliations table; a long one is an
        # address written out, which is the pre-split layout and still builds.
        # The distinction has to hold with the table empty too: `A` with
        # nothing defined puts the letter A in the byline where the department
        # goes, and that is the state a half-migrated project is in.
        keyish = bool(parts) and all(len(p) <= 3 for p in parts)
        unknown = [p for p in parts if p not in affs]
        if not cell:
            add("gap", f"{r['name']} has no affiliation")
        elif not keyish and len(cell) >= 24:
            pass                     # an address, written out in full
        elif not unknown:
            pass                     # every key resolves
        elif len(unknown) == len(parts):
            add("blocking",
                f"{r['name']} is in affiliation {cell}, which "
                f"affiliations.md does not define",
                "affiliations.md")
        elif unknown:
            add("blocking",
                f"{r['name']} is in affiliations {cell} and "
                f"{', '.join(unknown)} is not defined",
                "affiliations.md")
        if r["orcid"] and not ORCID_RE.match(r["orcid"].strip()):
            add("blocking",
                f"{r['name']}'s ORCID is not an ORCID: {r['orcid']}")

    corr = info.get("corresponding", "")
    if not corr and len(rows) > 1:
        add("gap", "no corresponding author is named")
    elif corr:
        who = [r for r in rows
               if r["name"].lower() in corr.lower()
               or (r["email"] and r["email"].lower() in corr.lower())]
        if not who:
            add("blocking", f"the corresponding author line names {corr!r}, "
                            f"who is not in the author list")
        elif not who[0]["email"] and "@" not in corr:
            add("gap", f"{who[0]['name']} is corresponding and has no email")

    used = {a for r in rows for a in _aff_texts(r, affs)}
    for k, v in affs.items():
        if v not in used:
            add("gap", f"affiliation {k} is defined and nobody is in it",
                "affiliations.md")

    if not contrib["rows"] and rows:
        add("gap", "the contribution matrix is empty - no author has a role, "
                   "so there is no CRediT statement to submit")
    matched: set[str] = set()
    for c in contrib["rows"]:
        who = match_author(c["author"], rows) if rows else None
        if rows and not who:
            add("blocking", f"the contribution matrix credits {c['author']}, "
                            f"who is not in the author list")
        if who:
            matched.add(_name_key(who["name"]))
        if not c["roles"]:
            add("gap", f"{c['author']} has no contribution marked - an author "
                       f"with no role is not an author")
    if contrib["rows"]:
        for r in rows:
            if _name_key(r["name"]) not in matched:
                add("gap",
                    f"{r['name']} has no row in the contribution matrix")

    for g in info["funding"]["grants"]:
        if g["to"] and rows and not match_author(g["to"], rows):
            add("gap", f"the grant {g['funder']} is held by {g['to']}, who is "
                       f"not in the author list",
                "affiliations.md")

    return {
        "authors": rows,
        "corresponding": corr,
        "affiliations": affs,
        "contributions": contrib,
        "funding": info["funding"],
        "byline": author_block(info),
        "contributions_statement": contributions_statement(info),
        "funding_statement": funding_statement(info),
        "findings": found,
        "blocking": sum(1 for f in found if f["severity"] == "blocking"),
    }


def _yaml_scalar(s: str) -> str:
    return '"' + (s or "").replace("\\", "\\\\").replace('"', '\\"') + '"'


def drafted_sections(project: str) -> list[str]:
    """The body sections that have prose in them.

    As against the scaffold's empty form: a heading with nothing under it is
    a section nobody has written yet, and the two have to be told apart
    before anything is refused over one.
    """
    st = source_text_dir(project)
    out: list[str] = []
    for stem in section_files(project):
        if stem == "title_abstract":
            continue
        raw = re.sub(r"<!--.*?-->", "",
                     _read(os.path.join(st, stem + ".md")), flags=re.DOTALL)
        if _split_heading(raw)[1].strip():
            out.append(stem)
    return out


def front_matter(project: str, blind: bool = False,
                 subtitle: str = "") -> tuple[str, dict, list[str]]:
    """The pandoc metadata block for title, authors and abstract; what was
    read out of the form; and what is still missing from it.

    `blind` is a double-blind (anonymized) build, and it is item 129. The
    byline goes in the metadata, so pandoc sets it both as the Author
    paragraphs of the document AND as `dc:creator` in `docProps/core.xml` -
    two places, one of which nobody thinks to look at. Leaving it out here
    is what takes it out of both; there is no second edit to remember.
    """
    st = source_text_dir(project)
    ta = parse_title_abstract(_read(os.path.join(st, "title_abstract.md")))
    info = author_record(project)
    gaps: list[str] = []
    lines = ["---"]
    if ta["title"]:
        lines.append("title: " + _yaml_scalar(ta["title"]))
    else:
        gaps.append("the manuscript has no title yet")
        lines.append("title: " + _yaml_scalar(
            "[FLAG: author] this manuscript has no title yet"))
    # Item 138. pandoc sets `subtitle` directly under the title, ahead of the
    # byline and the abstract - the conventional place for a running title,
    # and the one place a body block can never reach, because every body
    # block renders after the metadata.
    if subtitle:
        lines.append("subtitle: " + _yaml_scalar(subtitle))
    authors = [] if blind else author_block(info)
    if blind:
        # Not a gap and not a flag: an empty byline is the REQUIREMENT here,
        # and a `**[FLAG: author]**` reading "no author list yet" in a file
        # deliberately built without one would send the author to fix the
        # thing the journal asked for.
        pass
    elif authors:
        lines.append("author:")
        lines += ["  - " + _yaml_scalar(a) for a in authors]
    else:
        gaps.append("the author table is empty, so the build has no byline")
        lines.append("author:")
        lines.append("  - " + _yaml_scalar(
            "**[FLAG: author]** no author list yet - fill in the table in "
            f"{fm_rel(project, 'authors')}"))
    if ta["abstract"]:
        lines.append("abstract: |")
        lines += ["  " + ln for ln in ta["abstract"].split("\n")]
    else:
        gaps.append("the abstract is still a stub")
    lines.append("---")
    return "\n".join(lines) + "\n", ta, gaps


# ---------------------------------------------------------------------------
# anonymized (double-blind) review - item 129
# ---------------------------------------------------------------------------
#
# `requirements.yml` has carried an `anonymization:` block since the IJROBP
# capture was written, and its own comment said "Not read by the engine" -
# which was true, and was the defect. The build rendered the author list, the
# affiliations, the corresponding author and `dc:creator` into a manuscript
# whose journal requires none of them to be there, appended a PAPER NOT
# COMPLETE block naming an author, and warned about none of it. A member
# following the engine would have uploaded a deanonymized file to a
# double-blind journal.
#
# What is fixed here is everything the engine can settle by itself. What it
# CANNOT settle is which reference is the authors' own prior work - a shared
# surname is not a shared person - so that half is measured, named in the
# summary with the journal's own masking rule quoted, and left to the author.
# It is deliberately NOT written into the manuscript: a flag inside a blinded
# file listing the authors' own papers is the disclosure it exists to prevent.

def anonymized_review(req: dict) -> bool:
    """Does this journal review this article type double-blind?"""
    v = (req.get("anonymization.required") or "").strip().lower()
    return v in ("true", "yes", "required", "1")


def _blind_filler(req: dict) -> str:
    """The journal's own filler, first word of `anonymization.filler`.

    ASTRO's is `XXXX, Anonymized for Review, or ****` - three it accepts, and
    the first one is taken rather than a house default, because the point of
    reading the block at all is that the journal decides.
    """
    raw = (req.get("anonymization.filler") or "").strip()
    first = re.split(r"[,;]| or ", raw)[0].strip() if raw else ""
    return first or "XXXX"


def _blind_names(project: str) -> list[str]:
    """Every string that names a person or a place on this paper's byline.

    Longest first, so replacing `Kendra Westwood` never leaves `Westwood`
    behind because `Kenneth` matched a shorter entry first.
    """
    info = author_record(project)
    out: set[str] = set()
    for r in info.get("authors") or []:
        if r.get("name"):
            out.add(r["name"].strip())
            last = r["name"].strip().split()[-1]
            if len(last) > 2:
                out.add(last)
        if r.get("email"):
            out.add(r["email"].strip())
    for a in (info.get("affiliations") or {}).values():
        if isinstance(a, str) and a.strip():
            out.add(a.strip())
    return sorted((s for s in out if s), key=len, reverse=True)


def blind_text(text: str, names: list[str], filler: str = "XXXX") -> str:
    """The same text with every byline name replaced by the journal's filler.

    Used on the PAPER NOT COMPLETE block, which is GENERATED and therefore
    the one part of a blinded build nobody proof-reads: it said `Kenneth
    Westwood is corresponding and has no email` inside a file built for
    double-blind review.
    """
    for n in names:
        if not n:
            continue
        text = re.sub(r"(?<![\w@.])%s(?![\w@.])" % re.escape(n), filler, text)
    return text


# Item 154. A FLAG in a blinded file may ask for a fact and never for an
# identifier: following "[FLAG: author - <institution> IRB protocol number]"
# breaks the anonymization the journal requires, and the check that read what
# the text contained could not see what a FLAG asked for.
FLAG_SPAN_RE = re.compile(r"\[FLAG[^\]]*\]")
IDENTIFIER_ASK_RE = re.compile(
    r"\b(?:protocol|approval|reference|registration|ethics|irb|trial|study)"
    r"\s+(?:number|no\.?|id|identifier|code)\b"
    r"|\birb\s*(?:#|number|no\.?|id)\b"
    r"|\bNCT\s?\d|\bclinicaltrials\.gov\b|\bregistry\s+(?:number|id)\b"
    r"|\b(?:name|names)\s+of\s+the\s+(?:institution|irb|ethics|hospital|"
    r"committee|university)\b|\bwhich\s+(?:institution|irb|hospital)\b",
    re.IGNORECASE)


def blind_flags(text: str, names: list[str], filler: str = "XXXX") -> str:
    """Every byline name inside a FLAG replaced by the filler - and only
    inside a FLAG, because the body of a blinded paper cites its own authors'
    earlier work under their names and those are named, never masked."""
    return FLAG_SPAN_RE.sub(lambda m: blind_text(m.group(0), names, filler),
                            text or "")


def identifier_flags(text: str) -> list[str]:
    """The FLAGs in a text that ask for an identifying detail."""
    return [m.group(0) for m in FLAG_SPAN_RE.finditer(text or "")
            if IDENTIFIER_ASK_RE.search(m.group(0))]


# Item 149. Where a required statement lives when the journal's section order
# has no slot for it. Ethics approval is stated with the patient cohort, in
# the first Methods subsection; a statement given a heading the order does
# not list is a section an editor screens out.
STATEMENT_HOMES = {"ethics": "methods"}


def inline_statement(section_md: str, statement_md: str) -> str:
    """A statement's text, headingless, at the end of a section's first
    subsection (or of its first paragraph when it has none)."""
    body = "\n".join(ln for ln in statement_md.strip().split("\n")
                     if not _ATX_RE.match(ln)).strip()
    if not body:
        return section_md
    lines = section_md.split("\n")
    heads = [i for i, ln in enumerate(lines) if _ATX_RE.match(ln)]
    subs = heads[1:] if heads and heads[0] == 0 else heads
    if subs:
        nxt = next((i for i in heads if i > subs[0]), len(lines))
        lines[nxt:nxt] = ["", body, ""] if nxt < len(lines) else ["", body]
        return re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip()
    paras = re.split(r"\n\s*\n", section_md.strip())
    at = 2 if paras and _ATX_RE.match(paras[0]) else 1
    paras[at:at] = [body]
    return "\n\n".join(paras)


# Which title-page element the byline block at the top already supplies.
# Matched on the journal's own words for it, because the list is the
# journal's: ASTRO says `authors' names, degrees and affiliations` where
# another says `author list`.
TITLE_PAGE_IN_BYLINE = {
    "title": ("title",),
    "running_title": ("running title", "short title", "running head"),
    "byline": ("authors' names", "authors’ names", "author names",
               "author list", "byline", "all authors"),
    "affiliations": ("affiliation", "institution"),
    "corresponding": ("corresponding",),
}

# A title-page element that says `author` and is NOT the byline. ASTRO wants
# the `author(s) responsible for statistical analyses - name, telephone,
# mailing address, e-mail`, which is a NAMED PERSON WITH AN ADDRESS and not
# something the byline answers; a matcher keyed on the word `author` ticked
# it off against the author list and the element went unwritten with nothing
# saying so.
TITLE_PAGE_NOT_THE_BYLINE = ("responsible for", "statistical analys",
                             "statistician")

# Which statement in `authors.md` answers a title-page element. Matched on
# the journal's phrasing rather than on the authors.md heading, because the
# two are rarely the same words - ASTRO asks for a `conflict of interest
# statement` and authors.md collects `Competing interests`, and a matcher
# keyed on the heading found neither that nor `data sharing statement`.
TITLE_PAGE_STATEMENT_WORDS = {
    "conflict_of_interest": ("conflict of interest", "competing interest",
                             "disclosure", "declaration of interest"),
    "funding": ("funding", "financial support", "grant support"),
    "data_availability": ("data sharing", "data availability",
                          "data statement"),
    "acknowledgment": ("acknowledg",),
    "author_contributions": ("contribution", "credit"),
    "ethics": ("ethics", "ethical approval", "irb"),
    "supporting_information": ("supporting information", "supplementary"),
}


def title_page_checklist(project: str, journal: str, req: dict,
                         ta: dict, info: dict) -> list[dict]:
    """The journal's own title-page list, one row per element, answered.

    Item 129's second half. `submission-package` already wrote a title page,
    and it wrote the SAME five sections for every journal - title, running
    head, authors, counts, keywords - while the conflict-of-interest,
    funding, data-sharing and clinical-trial statements ASTRO requires ON
    THAT PAGE went into `statements_rN.md`, a file no journal asked for. So
    the document existed and was missing most of what it is for.

    `structure.title_page_statements` is the journal's own list and is used
    VERBATIM: every entry becomes a row, answered from `authors.md` where
    authors.md holds it, marked `carried above` where the byline block
    already supplies it, and flagged where neither is true. Nothing is
    dropped and nothing is invented - a title page is a checklist an editor
    screens on, and an element that is silently absent is the one failure
    mode worth designing against.

    Returns rows, not markdown, so that the one builder of this document
    stays the one builder of this document.
    """
    wanted = _req_list(req, "structure.title_page_statements")
    if not wanted:
        return []
    have = {"title"} if ta.get("title") else set()
    block = author_block(info)
    if block:
        have |= {"byline", "affiliations"}
        if any(ln.lstrip(r"\*").startswith("Corresponding")
               for ln in block):
            have.add("corresponding")
    if ta.get("running_title"):
        have.add("running_title")

    rows: list[dict] = []
    for want in wanted:
        low = want.lower()
        supplied = ([] if any(w in low for w in TITLE_PAGE_NOT_THE_BYLINE)
                    else sorted(t for t, words in TITLE_PAGE_IN_BYLINE.items()
                                if t in have
                                and any(w in low for w in words)))
        key = next((k for k, words in TITLE_PAGE_STATEMENT_WORDS.items()
                    if any(w in low for w in words)), "")
        text = (_statement_text(project, STATEMENT_HEADINGS[key][1])
                if key and STATEMENT_HEADINGS[key][1] else "").strip()
        rows.append({"want": want, "key": key, "text": text,
                     "carried": supplied,
                     "state": "written" if text
                              else "carried" if supplied else "missing"})
    # Item 154. On a blinded paper the ethics statement in the manuscript
    # names no board and no protocol number, so those have to be SOMEWHERE -
    # and the title page is the document reviewers do not see.
    if (anonymized_review(req) and statement_status(req, "ethics")
            and not any(r["key"] == "ethics" for r in rows)):
        text = _statement_text(project, STATEMENT_HEADINGS["ethics"][1])
        rows.append({"want": "ethics board and approval or protocol number "
                             "(identifying, so here and not in the "
                             "anonymized manuscript)",
                     "key": "ethics", "text": text.strip(), "carried": [],
                     "state": "written" if text.strip() else "missing"})
    return rows


def _bib_authors(project: str) -> dict:
    """citekey -> the author field of its .bib entry, lowercased."""
    path = os.path.join(drafts_dir(project), "references.bib")
    if not os.path.isfile(path):
        return {}
    out: dict[str, str] = {}
    key = ""
    for m in re.finditer(r"@\w+\s*\{\s*([^,\s}]+)\s*,(.*?)(?=\n@|\Z)",
                         _read(path), re.S):
        key = m.group(1).strip()
        a = re.search(r"^\s*author\s*=\s*[{\"](.*?)[}\"]\s*,?\s*$",
                      m.group(2), re.S | re.M)
        out[key] = (a.group(1) if a else "").lower()
    return out


def self_citations(project: str) -> list[dict]:
    """References whose author list carries a surname from this byline.

    A CANDIDATE, never a verdict. Two people share a surname, and masking a
    stranger's paper destroys a citation as surely as leaving one's own
    unmasked breaks the blinding - so this names what to look at and the
    author decides. The journal's own rule for what to do is quoted beside
    it, out of `references.anonymize_self_citations`.
    """
    info = author_record(project)
    surnames = sorted({r["name"].strip().split()[-1].lower()
                       for r in (info.get("authors") or [])
                       if r.get("name") and len(r["name"].split()[-1]) > 2})
    if not surnames:
        return []
    out = []
    for key, authors in sorted(_bib_authors(project).items()):
        hit = [s for s in surnames
               if re.search(r"(?<![\w-])%s(?![\w-])" % re.escape(s), authors)]
        if hit:
            out.append({"key": key, "surnames": hit})
    return out


# ---------------------------------------------------------------------------
# the end matter - sections a journal asks for that no source file holds
# ---------------------------------------------------------------------------

# The group's own accepted Langmuir paper ends ASSOCIATED CONTENT / AUTHOR
# INFORMATION / Corresponding Author / Funding Sources / ACKNOWLEDGMENT /
# AUTHOR CONTRIBUTIONS / REFERENCES. Nothing in this pipeline generated any of
# it. authors.md has collected funding, competing interests, data availability
# and acknowledgements since the scaffold was written and none of it ever
# reached the .docx, while requirements.yml already records which of them the
# journal requires - so the build had everything it needed and used none of it.
#
# key, the heading used when the journal named none, and the heading in
# authors.md the text is read from.
STATEMENT_BLOCKS = [
    ("supporting_information", "Supporting Information",
     "Supporting Information"),
    ("author_information", "Author Information", ""),
    ("author_contributions", "Author Contributions",
     "Contributions (CRediT)"),
    ("funding", "Funding", "Funding"),
    ("conflict_of_interest", "Conflict of Interest", "Competing interests"),
    ("data_availability", "Data Availability", "Data and code availability"),
    ("ethics", "Ethics", "Ethics"),
    ("acknowledgment", "Acknowledgements", "Acknowledgements"),
]
STATEMENT_HEADINGS = {k: (h, src) for k, h, src in STATEMENT_BLOCKS}


def statement_status(req: dict, key: str) -> str:
    """`required`, `encouraged`, `required_if_used` or "" - as the journal put
    it. Read from structure.statement_sections, from a two-level spelling of
    the same key, or from the skeleton's structure.required_statements list."""
    for k in ("structure.statement_sections.%s" % key, "structure.%s" % key):
        v = (req.get(k) or "").strip().lower()
        if v and v not in ("unknown", "null", "none"):
            return v
    lst = (req.get("structure.required_statements") or "").strip().lower()
    if lst and lst not in ("unknown", "null", "none"):
        if key.replace("_", " ") in lst.strip("[]"):
            return "required"
    return ""


# A file staged for upload whose name says what it is. Deliberately narrow:
# "supporting_information.pdf", "Supplementary Tables.docx", "SI-appendix.pdf".
# A word boundary is required after the prefix so that "significance.md" and
# "supplement" written as part of a longer word are not read as an SI upload.
SI_FILE_RE = re.compile(r"^(supporting|supplement\w*|si)\b[ _.-]", re.I)


def statement_applies(project: str, key: str,
                      journal: str | None = None) -> tuple[bool | None, str]:
    """For a `required_if_used` statement, whether the thing it describes
    exists here: True, False, or None for "cannot tell from this folder".

    Only `supporting_information` has an answer the project can give, and it
    is a real one: a supplementary float, or a file staged for upload whose
    name says what it is. Whether a study was funded, or had human subjects,
    is a fact only a human has - so every other key comes back None, and an
    unknown never becomes a `**[FLAG: ...]**` in the manuscript body. That is
    the test item 22 settled: a flag is for a question an author can answer.
    """
    if key != "supporting_information":
        return None, ""
    if _statement_text(project, STATEMENT_HEADINGS[key][1]):
        return True, "the statement is already written"

    # The float set, from both halves of it - the captions are what the
    # manuscript claims exists, the folders are what has actually been drawn,
    # and a supplementary entry in either one is supporting information.
    caps = _prose(project, "captions")
    for e in caps.get("floats", []):
        if e.get("supplementary"):
            return True, "%s is captioned" % e.get("label", "a float")
    dirs = _scaffold_floats(project)
    for f in dirs.get("floats", []):
        if f.get("supplementary"):
            return True, "%s is a supplementary float folder" % f["dir"]

    for d in ([submission_dir(project, journal)] if journal else []) + [
            source_text_dir(project), drafts_dir(project)]:
        if not os.path.isdir(d):
            continue
        for name in sorted(os.listdir(d)):
            if SI_FILE_RE.match(name):
                return True, "%s is staged for upload" % name

    # Nothing found - but "nothing found" is only an answer where this
    # project's own folders are the place to look.
    if "floats" not in read_scope(project, journal):
        return None, ("this project's float set is managed outside it "
                      "(writing_config.yml: manages), so a supplementary "
                      "figure or table would not be visible from here")
    unreadable = str(caps.get("error") or dirs.get("error") or "")
    if unreadable:
        return None, unreadable
    return False, ("no supplementary float is captioned or drawn, and no "
                   "supporting-information file is staged")


def statement_required(project: str, req: dict, key: str,
                       journal: str | None = None) -> tuple[bool, str]:
    """Whether this journal is owed the statement, and the line to say when
    nobody can tell.

    `statement_status` returns the journal's own three words and the one
    consumer that matters used to throw the distinction away with
    `status.startswith("required")` - so Langmuir's
    `supporting_information: required_if_used`, which is correct and is the
    journal's own wording, put **[FLAG: author] this journal requires a
    supporting information statement** into a paper that has no supporting
    information. Nothing about that flag needed an author (item 40).

    `required` is owed exactly as before. `encouraged` is not. A
    `required_if_used` is owed only when the thing it describes exists, and
    when that cannot be determined it is not owed and the reason is returned
    for the build summary rather than for the manuscript body.
    """
    status = statement_status(req, key)
    if status != "required_if_used":
        return status == "required", ""
    used, why = statement_applies(project, key, journal)
    if used is None:
        return False, ("this journal asks for a %s statement if there is one "
                       "to make and the engine cannot tell whether there is: "
                       "%s. No statement was written and no flag was raised - "
                       "add the section to %s if the paper needs one"
                       % (STATEMENT_HEADINGS.get(key, (key, ""))[0].lower(),
                          why, fm_rel(project, "authors")))
    return used, ""


def _statement_text(project: str, heading: str) -> str:
    """What is written under one heading, from whichever author file has it.

    Two files hold end matter - authors.md the people, and affiliations.md
    the money and the statements that go with it - and a project written
    before the split has all of it in the first. Both are read, first with
    content wins, so neither layout loses a statement.
    """
    if not heading:
        return ""
    for which in ("authors", "affiliations"):
        for text in front_matter_texts(project, which):
            body = _md_block(text, heading)
            if _has_content(body):
                return body.strip()
    return ""


def ai_statement_text(project: str) -> str:
    """What the author has actually declared, out of `ai_disclosure.md`.

    The stub's furniture comes off - the `#` heading, the `>` lines quoting
    the journal's own question, and the `<!-- -->` guidance - and what is left
    is the declaration. **Flags are kept verbatim**, because they are the gate:
    a file still carrying one has to reach the manuscript carrying one, or the
    build looks finished when it is not.

    Three callers had a copy of this - the paper section, the submission file
    and the cover letter - and the paper section's copy was the one that did
    not exist at all (item 115).
    """
    body = re.sub(r"<!--.*?-->", "",
                  _read(os.path.join(source_text_dir(project),
                                     "ai_disclosure.md")),
                  flags=re.DOTALL)
    body = re.sub(r"^[#>].*$", "", body, flags=re.M)
    return body.strip()


def statement_block(project: str, key: str, heading: str,
                    required: bool, level: int = 1) -> tuple[str, str]:
    """One end-matter section as markdown, and the gap it leaves when empty.

    `level` is the heading depth the journal's own order asked for (item 33):
    ACS puts Funding Sources and Notes *inside* AUTHOR INFORMATION, so those
    are `##` while the container above them is `#`.
    """
    src = STATEMENT_HEADINGS.get(key, ("", ""))[1]
    info = author_record(project)
    body = ""
    if key == "author_information":
        rows = info["authors"]
        corr = (info.get("corresponding") or "").lower()
        who = [r for r in rows
               if corr and (r["name"].lower() in corr
                            or bool(r["email"]) and r["email"].lower() in corr)]
        who = who or rows[:1]
        if who:
            r = who[0]
            where = "; ".join(_aff_texts(r, info.get("affiliations") or {}))
            body = "**Corresponding Author**\n\n" + " - ".join(
                x for x in (r["name"], where, r["email"]) if x)
            orcids = [x for x in rows if x["orcid"]]
            if orcids:
                body += "\n\n" + "\n\n".join(
                    "%s - ORCID %s" % (x["name"], x["orcid"]) for x in orcids)
    elif key == "author_contributions":
        # Written from the matrix rather than copied out of the file: the
        # matrix is where the ticks are, and the journal wants CRediT's own
        # wording, which nobody should have to type a second time. A project
        # that wrote its contributions as prose instead keeps that prose.
        body = contributions_statement(info)
        if not body and (info["contributions"]["form"] == "none"):
            # Only when there is no matrix at all. A matrix nobody has ticked
            # yet is an empty statement, and falling back to the block would
            # put the form's own headings in the manuscript.
            body = _statement_text(project, src)
    elif key == "funding":
        body = funding_statement(info)
    elif key == "ai_disclosure":
        # NOT from authors.md. Every other statement here is end matter the
        # author files write; this one has a file of its own (17.4) that the
        # `ai-disclosure` subcommand writes and the submission package reads,
        # and `ai_disclosure` is deliberately not in STATEMENT_BLOCKS - so the
        # generic path resolved its source heading to "" and flagged
        # authors.md for a statement that was never going to be there.
        body = ai_statement_text(project)
    else:
        body = _statement_text(project, src)
    if not body:
        if not required:
            return "", ""
        where = ("`%sai_disclosure.md`" % stpfx(project)
                 if key == "ai_disclosure" else
                 "`%s`" % fm_rel(
                     project,
                     "affiliations" if key in ("funding",
                                               "conflict_of_interest",
                                               "ethics", "acknowledgment")
                     else "authors"))
        art = "an" if heading[:1].lower() in "aeiou" else "a"
        return ("%s %s\n\n**[FLAG: author]** this journal requires %s %s "
                "statement and %s has none.\n"
                % ("#" * level, heading, art, heading.lower(), where),
                "%s is required by this journal and %s has none"
                % (heading, os.path.basename(where.strip("`"))))
    return "%s %s\n\n%s\n" % ("#" * level, heading, body.strip()), ""


# Where citeproc puts the bibliography. Without it pandoc appends the
# references after everything else in the file - after the acknowledgements
# and after the incomplete block, which is not where any journal's section
# order says they go.
REFS_PLACEHOLDER = "::: {#refs}\n:::"


# --- callouts are plain (item 146) -----------------------------------------
# `**Fig. 1D**` in the source text reached the .docx bold, all 24 callouts of
# a real build, and the cross-reference check read existence, order and label
# form and never emphasis. A caption's own bold lead (`**Figure 1.** The
# claim`) is NOT a callout and is not matched: the label must be closed by
# the emphasis marker directly, with no sentence after it.
CALLOUT_LABEL = (r"(?:Supplementary\s+)?(?:Figs?\.?|Figures?|Tables?|"
                 r"Movies?|Videos?|Schemes?|Eqs?\.?)\s*\(?[SE]?\d+[A-Za-z]?"
                 r"(?:\s*(?:[-\u2013,]|and)\s*[SE]?\d*[A-Za-z]?)*\)?")
CALLOUT_EMPHASIS_RE = re.compile(
    r"(?<![\w*])(\*\*|\*|__|_)(%s)\1(?![\w*])|<u>(%s)</u>"
    r"|\[(%s)\]\{\.underline\}" % (CALLOUT_LABEL, CALLOUT_LABEL,
                                   CALLOUT_LABEL))
CALLOUT_EMPHASIS_KEEP = ("bold", "italic", "underline", "emphasized")


def strip_callout_emphasis(md: str, req: dict) -> tuple[str, list[str]]:
    """The markdown with every emphasized callout set plain, and the
    callouts it changed - unless `typography.callout_emphasis` records that
    the journal wants them emphasized."""
    want = (req.get("typography.callout_emphasis") or "").strip().lower()
    if want in CALLOUT_EMPHASIS_KEEP:
        return md, []
    found: list[str] = []

    def plain(m: re.Match) -> str:
        label = m.group(2) or m.group(3) or m.group(4)
        found.append(label)
        return label
    out = []
    for line in (md or "").split("\n"):
        # A caption heading or a caption's bold lead line is left alone.
        if _ATX_RE.match(line):
            out.append(line)
            continue
        out.append(CALLOUT_EMPHASIS_RE.sub(plain, line))
    return "\n".join(out), found


# --- the citation form the CSL renders (item 141) --------------------------
#
# assemble passed style.csl to pandoc without comparing it with
# references.style_name. A community CSL for IJROBP renders (1); the
# journal's own guide says AMA, which is superscript. Two projects aimed at
# one journal reached submission in different citation forms and no check
# said so. The form is read out of the CSL itself; the one a style name
# implies is a small table, and a name it does not know is not judged.
STYLE_NAME_FORMS = {
    "ama": ("numeric", "superscript"),
    "american_medical_association": ("numeric", "superscript"),
    "acs": ("numeric", "superscript"),
    "american_chemical_society": ("numeric", "superscript"),
    "nature": ("numeric", "superscript"),
    "rsc": ("numeric", "superscript"),
    "ieee": ("numeric", "bracket"),
    "vancouver": ("numeric", ""),
    "nlm": ("numeric", ""),
    "apa": ("author-date", ""),
    "harvard": ("author-date", ""),
    "chicago_author_date": ("author-date", ""),
}
CANONICAL_CSL = "https://raw.githubusercontent.com/citation-style-language/" \
                "styles/master/%s.csl"
CANONICAL_CSL_NAMES = {
    "ama": "american-medical-association",
    "american_medical_association": "american-medical-association",
    "acs": "american-chemical-society",
    "american_chemical_society": "american-chemical-society",
    "nature": "nature", "ieee": "ieee", "vancouver": "vancouver",
    "apa": "apa", "harvard": "harvard-cite-them-right",
    "chicago_author_date": "chicago-author-date",
}


def csl_citation_form(csl: str) -> dict:
    """{"format": numeric | author-date | note | "", "form": superscript |
    bracket | parenthesis | ""} as the CSL file itself would render an
    in-text citation."""
    out = {"format": "", "form": ""}
    text = _read(csl) if csl and os.path.isfile(csl) else ""
    if not text:
        return out
    m = re.search(r'citation-format="([^"]+)"', text)
    out["format"] = m.group(1) if m else ""
    cit = re.search(r"<citation\b.*?</citation>", text, re.S)
    if not cit:
        return out
    block = cit.group(0)
    if re.search(r'vertical-align="sup"', block):
        out["form"] = "superscript"
    else:
        lay = re.search(r"<layout\b[^>]*>", block)
        pre = re.search(r'prefix="([^"]*)"', lay.group(0)) if lay else None
        p = (pre.group(1) if pre else "").strip()
        out["form"] = ("bracket" if p.startswith("[") else
                       "parenthesis" if p.startswith("(") else "")
    return out


def superscript_punctuation_args(csl: str) -> list:
    """Pandoc arguments that put a superscript citation AFTER the period or
    comma that follows it (item 159).

    AMA, ACS and Nature set a superscript outside periods and commas
    ("in real time.1"), and pandoc only moves the punctuation for an in-text
    style when notes-after-punctuation is set - its default is on for note
    styles alone - so a superscript CSL rendered "in real time1." A
    parenthetical or bracketed style is left exactly as it was."""
    if csl_citation_form(csl).get("form") == "superscript":
        return ["-M", "notes-after-punctuation=true"]
    return []


def citation_form_check(req: dict, csl: str) -> dict:
    """What style.csl renders against what references.style_name implies.

    `agrees` is True, False, or None where either side is unknown - a style
    name this table does not know is not judged."""
    name = _sec_key(req.get("references.style_name") or "")
    known = name not in ("", "unknown", "null", "none")
    fmt, form = STYLE_NAME_FORMS.get(name, ("", "")) if known else ("", "")
    have = os.path.isfile(csl) if csl else False
    got = csl_citation_form(csl) if have else {"format": "", "form": ""}
    res = {"style_name": req.get("references.style_name") or "",
           "expected_format": fmt, "expected_form": form,
           "csl_format": got["format"], "csl_form": got["form"],
           "csl_present": have, "agrees": None, "canonical": "",
           "detail": ""}
    if known and name in CANONICAL_CSL_NAMES:
        res["canonical"] = CANONICAL_CSL % CANONICAL_CSL_NAMES[name]
    if not have:
        if known:
            res["detail"] = (
                "there is no journal_requirements/style.csl and "
                "references.style_name is %s, so the citations are in "
                "pandoc's default style, not the journal's%s"
                % (res["style_name"],
                   " - the canonical CSL for it is %s" % res["canonical"]
                   if res["canonical"] else ""))
        return res
    if not fmt:
        return res
    bad = []
    if got["format"] and got["format"] != fmt:
        bad.append("it is %s and %s is %s" % (got["format"],
                                              res["style_name"], fmt))
    if form and got["form"] and got["form"] != form:
        bad.append("it renders %s citations and %s uses %s numbers"
                   % (got["form"], res["style_name"], form))
    res["agrees"] = not bad and bool(got["format"] or got["form"])
    if bad:
        res["agrees"] = False
        res["detail"] = ("style.csl contradicts references.style_name: %s%s"
                         % ("; ".join(bad),
                            ". The canonical CSL is %s" % res["canonical"]
                            if res["canonical"] else ""))
    return res

# An `@` that follows a word character or a tilde can never be the start of a
# citekey - pandoc's own citekey opener needs whitespace, `[`, or the start of
# a line before it. But a `~n~` subscript run butted against an `@` does
# desynchronise pandoc's parser, and it then invents citekeys out of the
# formula: `SiO~2~@Cu~2~GaBO~5~@TiO~2~` renders as
# `SiO₂(Cu~2~GaBO~5?)_((TiO?))2~` with two "citation not found" warnings, and
# the real reference beside it is dropped. Escaping that `@` is the whole fix
# (item 26); a real citekey is untouched because `[@key]` and `see @key` have
# `[` and a space in front, which this deliberately does not match.
#
# Code spans are not excluded: an assembled manuscript body is prose, and the
# engine never emits fenced code into source_text. A `\@` inside a code span
# would render its backslash literally, so revisit this if that ever changes.
_BARE_AT_RE = re.compile(r'(?<=[\w~])@')


def _escape_bare_at(md: str) -> str:
    """Escape every `@` pandoc cannot read as a citekey opener (item 26)."""
    return _BARE_AT_RE.sub(r'\\@', md)


def rscript() -> str | None:
    """R is installed here but is not on PATH, so `which Rscript` finds
    nothing. Look where it actually lives before reporting R missing."""
    found = shutil.which("Rscript")
    if found:
        return found
    import glob
    for pat in (r"C:\Program Files\R\R-*\bin\Rscript.exe",
                r"C:\Program Files\R\R-*\bin\x64\Rscript.exe"):
        hits = sorted(glob.glob(pat))
        if hits:
            return hits[-1]
    return None


def _enclosing_project(project: str) -> str | None:
    """The paper project this directory sits *inside*, if any.

    Walks up from the parent, so a project is never its own enclosing one.
    Stops at the filesystem root and at the drive root alike - a bare
    `while parent != path` loop spins forever on Windows when `dirname("C:\\")`
    returns `C:\\`.
    """
    path = os.path.abspath(project)
    seen = set()
    cur = os.path.dirname(path)
    while cur and cur not in seen:
        seen.add(cur)
        # A trimmed project has no project.yml and no drafts/ - source_text/
        # at the root is the whole of what marks it - so `init` pointed at
        # `<trimmed>/Langmuir/` has to find the root above it just the same.
        if (os.path.isfile(os.path.join(cur, "project.yml"))
                or source_text_folders(os.path.join(cur, "drafts"))
                or source_text_folders(cur)):
            return cur
        cur = os.path.dirname(cur)
    return None


def _scaffold_drafts(project: str, journal: str, dry_run: bool) -> dict:
    """Create drafts/ from scaffold.py's manifest, and nothing else.

    Shelled out like every other engine-to-engine call here, and for the same
    two reasons: the manifest stays the single source of truth for what the
    drafting subtree contains, and `tests/scaffold.py` already asserts that
    manifest and templates agree in both directions. A `--only drafts` run
    deliberately does not create plan/ or data/ - a project whose floats and
    analysis are managed elsewhere must not acquire an empty float pipeline
    as a side effect of being given a journal folder.
    """
    engine = os.path.join(HERE, "scaffold.py")
    if not os.path.isfile(engine):
        return _engine_failed(
            "scaffold.py", "scaffold --only drafts", (),
            "tools/scaffold.py is missing, so drafts/ cannot be created from "
            "the manifest; run setup-project-directory on this folder "
            "instead")
    cmd = [sys.executable, engine, "scaffold", project, "--only", "drafts",
           "--journal", journal, "--round",
           str(max(project_revision(project), 1)), "--json"]
    if dry_run:
        cmd.append("--dry-run")
    run = subprocess.run(cmd, capture_output=True, text=True,
                         encoding="utf-8", errors="replace")
    if not (run.stdout or "").strip():
        return _engine_failed(
            "scaffold.py", "scaffold --only drafts", (),
            f"wrote nothing: {(run.stderr or 'no output').strip()[:200]}")
    try:
        res = json.loads(run.stdout)
    except json.JSONDecodeError as e:
        return _engine_failed("scaffold.py", "scaffold --only drafts", (),
                              f"returned unparseable JSON: {e}")
    return {"created": res.get("created", [])}


def scopes_for(project: str, managed: list[str] | None = None) -> list[str]:
    """The scopes that APPLY to this project, in MANAGED_SCOPES order.

    A scope that does not apply is not "out of scope" - it is not a question.
    `analysis` is not a question for a narrative review and `corpus` is not
    one for a research paper, and reporting either as *managed elsewhere*
    puts a line in front of a coauthor that means nothing and has to be
    learned to be ignored.

    Anything the project DECLARES it manages applies whatever its kind, which
    is how a meta-analytic review holds both ledgers (spec 2) without a
    special case anywhere.
    """
    applies = set(SCOPE_DEFAULTS[paper_kind(project)]) | set(managed or [])
    return [s for s in MANAGED_SCOPES if s in applies]


def read_scope(project: str, journal: str | None) -> list[str]:
    """What this project manages in-tree, from the journal's writing_config.yml.

    No journal, or no config yet, means everything this paper KIND scaffolds
    with: the default has to be the full project, or the first run on a fresh
    scaffold would report the outline and the floats as somebody else's
    problem. It is not every member of MANAGED_SCOPES, because `analysis` and
    `corpus` belong to different paper kinds and a research project told it
    manages a corpus reports a missing data/corpus/ to its coauthors.
    """
    fallback = list(SCOPE_DEFAULTS[paper_kind(project)])
    if not journal:
        return fallback
    path = os.path.join(journal_dir(project, journal), "writing_config.yml")
    if not os.path.isfile(path):
        return fallback
    return read_config(path)["lists"].get("manages", fallback)


